       html:not(.dark) body.kv-home-route {
         --kv-bg: #F7F1E6;
         --kv-surface: #FFFCF6;
         --kv-surface-2: #F2E8D8;
         --kv-surface-3: #E9DAC2;
         --kv-border: #BFA986;
         --kv-text: #2A2118;
         --kv-text-muted: #574535;
         --kv-accent: #7A4A1F;
         --kv-accent-hover: #5F3817;
         --kv-success: #3F5A2E;
         --kv-warning: #8A560C;
         --kv-danger: #8E332A;
          --kv-radius: 16px;
          background: #F7F1E6;
        }
      html:not(.dark) body.kv-home-route .kv-container { max-width: 1280px; }
      html:not(.dark) body.kv-home-route .kv-footer { background: #F7F1E6; border-top: 1px solid #BFA986; color: #574535; }
      html:not(.dark) body.kv-home-route .kv-footer a { color: #574535; }
      html:not(.dark) body.kv-home-route .kv-footer a:hover { color: #7A4A1F; }
      body.kv-home-route .kv-home-banner { position: relative; margin: 14px 0 18px; }
