      .kv-admin-logo-icon img { height:100%; width:auto; max-width:180px; object-fit:contain; display:block; }

       .kv-comment-rules { margin: 0 0 20px; padding: 12px 14px; border: 0; border-left: 4px solid var(--kv-accent); border-radius: 0; background: transparent; }
       .kv-comment-reaction { margin: 16px 0 24px; padding: 14px 12px; border: 0; border-radius: 0; background: transparent; }
       .kv-comment-form { margin-top: 8px; }
       .kv-comment-sortbar { display: flex; align-items: center; gap: 8px; margin: 12px 0 8px; }
       .kv-comment-sortlabel { font-size: .75rem; color: var(--kv-text-muted); font-weight: 700; }

    .kv-comment-rules-head { display:flex; align-items:center; gap:8px; font-size:.78rem; font-weight:800; color:var(--kv-text); letter-spacing:.04em; text-transform:uppercase; margin-bottom:8px; }
    .kv-comment-rules-head svg { width:16px; height:16px; display:block; color:var(--kv-accent); }
    .kv-comment-rules-list { margin:0; padding-left:18px; display:grid; gap:4px; font-size:.8rem; line-height:1.5; color:var(--kv-text-muted); }
       .kv-comment-reaction { margin: 4px 0 12px; padding: 14px 12px; border: 0; border-radius: 0; background: transparent; }

    .kv-comment-reaction-label { font-size: .72rem; font-weight: 700; color: var(--kv-text-muted); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 10px; text-align: center; }
    .kv-manga-reaction-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 480px; margin: 0 auto; }
    .kv-manga-reaction { flex: 0 0 calc(33.333% - 8px); max-width: 150px; min-width: 110px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; padding: 12px 8px; border-radius: 14px; border: 1px solid var(--kv-border); background: var(--kv-surface-2); color: var(--kv-text-muted); cursor: pointer; transition: border-color .15s ease, transform .15s ease, color .15s ease, background-color .15s ease; }
    .kv-manga-reaction:hover { transform: translateY(-2px); border-color: var(--kv-accent); color: var(--kv-text); }
    .kv-manga-reaction.active { border-color: var(--kv-accent); color: var(--kv-accent); background: var(--kv-surface); }
    .kv-manga-reaction-emoji { font-size: 1.5rem; line-height: 1; }
    .kv-manga-reaction-count { font-size: .82rem; font-weight: 800; font-variant-numeric: tabular-nums; }
    .kv-manga-reaction-label { font-size: .7rem; font-weight: 600; text-align: center; line-height: 1.2; }
    .kv-comment-toggle-replies { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--kv-border); background: transparent; color: var(--kv-accent); font-size: .74rem; font-weight: 700; cursor: pointer; transition: background-color .15s ease, border-color .15s ease; }
    .kv-comment-toggle-replies:hover { background: var(--kv-surface-2); border-color: var(--kv-accent); }
    .kv-comment-toggle-replies svg { width: 14px; height: 14px; transition: transform .2s ease; }
    .kv-comment-toggle-replies.is-open svg { transform: rotate(180deg); }
    .kv-comment-action svg { width:16px; height:16px; }

    .kv-comment-scope-note { margin:0 0 10px; font-size:.74rem; color:var(--kv-text-muted); }
    .kv-comment-chapter-badge { display:inline-flex; align-items:center; padding:1px 7px; border-radius:6px; background:var(--kv-surface); color:var(--kv-accent); font-size:.64rem; font-weight:700; letter-spacing:.02em; }
    .kv-comment-pinned { display:inline-flex; align-items:center; gap:4px; padding:2px 8px; border-radius:999px; background:var(--kv-surface); color:var(--kv-accent); font-size:.62rem; font-weight:800; text-transform:uppercase; letter-spacing:.05em; }
    .kv-comment-pinned svg { width:12px; height:12px; display:block; }
    .kv-comment-action-danger { color:var(--kv-text-muted); }
    .kv-comment-action-danger:hover { color:#ef4444; border-color:#ef4444; }
    .kv-comment-image { max-width: 100%; max-height: 360px; border-radius: 12px; display: block; margin-top: 8px; border: 1px solid var(--kv-border); object-fit: cover; }
      .kv-comment-image-btn { display: inline-flex; align-items: center; justify-content: center; width: 38px; height: 38px; padding: 0; }
      .kv-comment-image-btn svg { width: 18px; height: 18px; display: block; }
      .kv-spoiler { border: 1px solid var(--kv-border); border-radius: 10px; margin: 8px 0; overflow: hidden; background: var(--kv-surface-2); }
      .kv-spoiler-toggle { display: flex; align-items: center; gap: 8px; width: 100%; padding: 10px 12px; background: transparent; border: 0; color: var(--kv-text-muted); font-size: .78rem; font-weight: 600; cursor: pointer; text-align: left; }
      .kv-spoiler-toggle:hover { background: var(--kv-surface-2); color: var(--kv-text); }
      .kv-spoiler-body { display: none; padding: 12px; border-top: 1px solid var(--kv-border); color: var(--kv-text); background: var(--kv-surface); white-space: pre-wrap; }
      .kv-spoiler.open .kv-spoiler-body { display: block; }
      .kv-spoiler-state-close { display: none; }
      .kv-spoiler.open .kv-spoiler-state-close { display: inline; }
      .kv-spoiler.open .kv-spoiler-state-open { display: none; }
       .kv-reply-to { display: inline-flex; align-items: center; background: rgba(101,88,217,.18); color: var(--kv-accent); padding: 2px 7px; border-radius: 999px; font-size: .68rem; font-weight: 600; margin-right: 6px; }
       .kv-md-card { display: flex; flex-direction: column; gap: 14px; }
       .kv-md-head { display: flex; align-items: center; gap: 12px; }
       .kv-md-head-icon { width: 40px; height: 40px; border-radius: 10px; background: var(--kv-surface-2); display: flex; align-items: center; justify-content: center; color: var(--kv-accent); }
        .kv-md-form { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 8px; align-items: center; }
        .kv-md-form .kv-input { min-width: 0; width: 100%; }

       .kv-md-tips { margin: 0; padding-left: 18px; color: var(--kv-text-muted); font-size: .8rem; display: grid; gap: 4px; }
       .kv-md-progress { margin-top: 12px; }
       .kv-md-progress-head { display: flex; justify-content: space-between; font-size: .8rem; color: var(--kv-text-muted); margin-bottom: 6px; }
       .kv-md-progress-bar { height: 8px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; }
       .kv-md-progress-fill { height: 100%; background: var(--kv-accent); border-radius: 999px; }
       .kv-traffic { margin-top: 20px; }
       .kv-traffic-toolbar { display: flex; align-items: end; gap: 14px; flex-wrap: wrap; background: var(--kv-surface); padding: 14px 16px; border-radius: 13px; margin-bottom: 20px; border: 1px solid var(--kv-border); }
       .kv-traffic-field { display: flex; flex-direction: column; gap: 7px; min-width: 150px; flex: 1; }
       .kv-traffic-field label { font-size: 11px; color: var(--kv-text-muted); letter-spacing: .04em; font-weight: 700; }
       .kv-traffic-field select, .kv-traffic-field input { height: 38px; border: 1px solid var(--kv-border); background: var(--kv-surface-2); color: var(--kv-text); border-radius: 7px; padding: 0 10px; font-size: 12px; }
       .kv-traffic-cards { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; margin-bottom: 20px; }
       .kv-traffic-card { position: relative; overflow: hidden; background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 13px; padding: 22px 22px 18px; min-height: 132px; }
       .kv-traffic-card:before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--kv-accent); }
       .kv-traffic-card:nth-child(2):before { background: #9b91ff; }
       .kv-traffic-card:nth-child(3):before { background: #e3c96a; }
       .kv-traffic-card:nth-child(4):before { background: #68c9b0; }
       .kv-traffic-label { font-size: 11px; letter-spacing: .055em; color: var(--kv-text-muted); font-weight: 700; }
       .kv-traffic-value { font-size: 29px; font-weight: 750; letter-spacing: -.03em; margin: 14px 0 7px; color: var(--kv-text); }
       .kv-traffic-note { font-size: 10px; color: var(--kv-text-muted); }
       .kv-traffic-chart { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 14px; padding: 22px; }
       .kv-traffic-legend { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; margin: 25px 0 7px; font-size: 10px; color: var(--kv-text-muted); }
       .kv-traffic-legend span { display: flex; align-items: center; gap: 6px; }
       .kv-traffic-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
       .kv-traffic-grid { stroke: var(--kv-border); stroke-width: 1; opacity: .65; }
       .kv-traffic-axis { fill: var(--kv-text-muted); font-size: 10px; }
        .kv-traffic-line { fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
        .kv-traffic-point-dot { pointer-events: none; }
        .kv-traffic-hit { fill: transparent; cursor: pointer; outline: none; }
        .kv-traffic-hit.is-selected { fill: rgba(242,169,59,.12); stroke: var(--ad-amber); stroke-width: 1; }
        .kv-traffic-hit:focus-visible { stroke: var(--ad-teal); stroke-width: 2; }
        .kv-traffic-tooltip { position: fixed; z-index: 120; width: 250px; max-width: calc(100vw - 20px); box-sizing: border-box; padding: 12px 13px; border: 1px solid rgba(255,255,255,.16); border-radius: 4px; background: #0D1116; color: #EAF1F4; box-shadow: 0 18px 40px -26px rgba(0,0,0,.9); opacity: 0; transform: translateY(4px); transition: opacity .14s ease, transform .14s ease; }
        .kv-traffic-tooltip[hidden] { display: none; }
        .kv-traffic-tooltip.is-visible { opacity: 1; transform: none; }
        .kv-traffic-tip-head { font-family: 'Plus Jakarta Sans', sans-serif; font-size: .78rem; font-weight: 600; letter-spacing: -.01em; }
        .kv-traffic-tip-row { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-top: 8px; font-size: .68rem; color: #92A5B2; }
        .kv-traffic-tip-row span { display: flex; align-items: center; gap: 7px; }
        .kv-traffic-tip-row i { width: 7px; height: 7px; border-radius: 2px; flex: 0 0 auto; }
        .kv-traffic-tip-row strong { font-family: 'JetBrains Mono', monospace; font-size: .72rem; font-weight: 600; color: #EAF1F4; }
        .kv-traffic-tip-foot { margin-top: 10px; padding-top: 8px; border-top: 1px solid rgba(255,255,255,.12); font-family: 'JetBrains Mono', monospace; font-size: .56rem; line-height: 1.5; color: #92A5B2; }
        @media (max-width: 800px) { .kv-traffic-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
       @media (max-width: 460px) { .kv-traffic-cards { grid-template-columns: 1fr 1fr; } .kv-traffic-value { font-size: 24px; } }
       .kv-admin-chapter-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
       .kv-admin-chapter-card-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
       .kv-admin-chapter-card-title { flex: 1; min-width: 0; font-weight: 600; color: var(--kv-text); font-size: .9rem; overflow-wrap: anywhere; }
       .kv-admin-chapter-card-date { color: var(--kv-text-muted); font-size: .75rem; }
       .kv-admin-chapter-card-progress { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
       .kv-admin-chapter-card-bar { flex: 1; min-width: 120px; height: 6px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; }
       .kv-admin-chapter-card-barfill { height: 100%; background: var(--kv-accent); border-radius: 999px; }
       .kv-admin-chapter-card-actions { display: flex; gap: 6px; flex-wrap: wrap; }
       .kv-admin-chapter-card-list { display: flex; flex-direction: column; gap: 10px; margin-top: 16px; }
       .kv-spinner { display: inline-block; width: 16px; height: 16px; border: 2px solid var(--kv-border); border-top-color: var(--kv-accent); border-radius: 50%; animation: kv-spin .7s linear infinite; }
       @keyframes kv-spin { to { transform: rotate(360deg); } }
       .kv-upload-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.6); display: flex; align-items: center; justify-content: center; z-index: 9999; }
       .kv-upload-box { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 12px; padding: 24px 28px; min-width: 320px; max-width: 90vw; text-align: center; box-shadow: 0 10px 40px rgba(0,0,0,.4); }
       .kv-upload-title { font-weight: 700; font-size: 1.1rem; color: var(--kv-text); margin-bottom: 6px; }
       .kv-upload-sub { color: var(--kv-text-muted); font-size: .8rem; margin-bottom: 14px; overflow-wrap: anywhere; }
       .kv-upload-bar { height: 8px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; margin-bottom: 10px; }
       .kv-upload-bar-fill { height: 100%; background: var(--kv-accent); border-radius: 999px; transition: width .2s ease; }
       .kv-upload-count { color: var(--kv-text-muted); font-size: .8rem; }
       .kv-upload-close { position: absolute; top: 8px; right: 10px; border: 0; background: transparent; color: var(--kv-text-muted); font-size: 1.4rem; cursor: pointer; line-height: 1; }
       .kv-upload-box { position: relative; }
       .kv-scrape-indicator { position: fixed; right: 12px; top: 50%; transform: translateY(-50%); z-index: 9999; background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 10px; padding: 8px 10px; display: flex; align-items: center; gap: 8px; box-shadow: 0 8px 22px -12px rgba(0,0,0,.4); }
       .kv-scrape-indicator-bar { width: 60px; height: 6px; background: var(--kv-surface-2); border-radius: 999px; overflow: hidden; }
       .kv-scrape-indicator-fill { height: 100%; background: var(--kv-accent); border-radius: 999px; }
       .kv-scrape-indicator-text { font-size: .75rem; color: var(--kv-text); font-weight: 600; }
       .kv-scrape-indicator-btn { border: 0; background: transparent; color: var(--kv-text-muted); cursor: pointer; font-size: 1rem; }
       .kv-admin-comments { display: flex; flex-direction: column; gap: 14px; }
       .kv-admin-comment-filters { display: flex; gap: 8px; flex-wrap: wrap; }
        .kv-admin-comment-count { font-size: .7rem; color: var(--kv-text-muted); }
       .kv-admin-comment-list { display: flex; flex-direction: column; gap: 10px; }
       .kv-admin-comment-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }
       .kv-admin-comment-card.is-pinned { border-color: var(--kv-accent); box-shadow: 0 0 0 1px rgba(101,88,217,.25); }
       .kv-admin-comment-head { display: flex; align-items: center; gap: 10px; }
       .kv-admin-comment-avatar { width: 36px; height: 36px; border-radius: 50%; object-fit: cover; flex: 0 0 36px; }
       .kv-admin-comment-avatar-fallback { display: flex; align-items: center; justify-content: center; background: var(--kv-surface-2); color: var(--kv-text); font-weight: 700; }
       .kv-admin-comment-meta { flex: 1; min-width: 0; }
       .kv-admin-comment-author { font-weight: 600; color: var(--kv-text); font-size: .875rem; }
       .kv-admin-comment-sub { color: var(--kv-text-muted); font-size: .75rem; overflow-wrap: anywhere; }
       .kv-admin-comment-body { color: var(--kv-text); font-size: .875rem; white-space: pre-wrap; overflow-wrap: anywhere; }
       .kv-admin-comment-img { max-width: 200px; max-height: 120px; border-radius: 8px; margin-top: 6px; object-fit: cover; border: 1px solid var(--kv-border); }
       .kv-admin-comment-actions { display: flex; gap: 6px; flex-wrap: wrap; }
       .kv-admin-leader-list { display: flex; flex-direction: column; gap: 8px; }
       .kv-admin-leader-row { display: flex; align-items: center; gap: 12px; padding: 10px 12px; border: 1px solid var(--kv-border); border-radius: 10px; background: var(--kv-surface); }
       .kv-admin-leader-rank { font-weight: 700; color: var(--kv-accent); width: 28px; text-align: center; }
       .kv-admin-leader-cover { width: 40px; height: 56px; border-radius: 6px; overflow: hidden; flex: 0 0 40px; }
       .kv-admin-leader-cover img { width: 100%; height: 100%; object-fit: cover; }
       .kv-admin-leader-body { flex: 1; min-width: 0; }
       .kv-admin-leader-title { font-weight: 600; color: var(--kv-text); font-size: .875rem; }
       .kv-admin-leader-meta { color: var(--kv-text-muted); font-size: .75rem; }
       .kv-admin-leader-barwrap { height: 6px; background: var(--kv-surface-2); border-radius: 999px; margin-top: 6px; overflow: hidden; }
       .kv-admin-leader-bar { height: 100%; background: var(--kv-accent); border-radius: 999px; }
       .kv-admin-leader-views { font-weight: 700; color: var(--kv-text); font-size: .875rem; white-space: nowrap; }
       .kv-admin-leader-views span { color: var(--kv-text-muted); font-weight: 400; font-size: .7rem; }
        .kv-admin-leader-actions { display: flex; gap: 6px; flex-wrap: wrap; }

      .kv-admin-shell.kv-admin-top {
        --ad-bg: #0B1015;
        --ad-panel: #121A22;
        --ad-raised: #18232D;
        --ad-line: #26343F;
        --ad-text: #EAF1F4;
        --ad-muted: #92A5B2;
        --ad-dim: #5F7482;
        --ad-amber: #F2A93B;
        --ad-amber-soft: rgba(242, 169, 59, .13);
        --ad-teal: #48D7B6;
        --ad-teal-soft: rgba(72, 215, 182, .11);
        --ad-red: #FF7077;
        --ad-shadow: 0 18px 44px -36px rgba(0, 0, 0, .95);
        background:
          radial-gradient(900px 460px at 92% -10%, var(--ad-teal-soft), transparent 62%),
          radial-gradient(620px 380px at -12% 4%, var(--ad-amber-soft), transparent 60%),
          var(--ad-bg);
        color: var(--ad-text);
        font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
      }
      html:not(.dark) .kv-admin-shell.kv-admin-top {
        --ad-bg: #F7F1E6;
        --ad-panel: #FFFCF6;
        --ad-raised: #F2E8D8;
        --ad-line: #BFA986;
        --ad-text: #2A2118;
        --ad-muted: #574535;
        --ad-dim: #705B45;
        --ad-amber: #8A560C;
        --ad-amber-soft: rgba(154, 101, 18, .12);
        --ad-teal: #65764A;
        --ad-teal-soft: rgba(95, 115, 82, .12);
        --ad-red: #8E332A;
        --ad-shadow: 0 16px 40px -34px rgba(58, 43, 20, .55);
      }
      .kv-admin-shell.kv-admin-top *,
      .kv-admin-shell.kv-admin-top *::before,
      .kv-admin-shell.kv-admin-top *::after { box-sizing: border-box; }
      .kv-admin-shell.kv-admin-top .kv-admin-content {
        background-image:
          linear-gradient(rgba(127, 153, 166, .045) 1px, transparent 1px),
          linear-gradient(90deg, rgba(127, 153, 166, .045) 1px, transparent 1px);
        background-size: 48px 48px;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-sidebar {
        width: 264px;
        padding: 22px 16px 18px;
        background: linear-gradient(180deg, var(--ad-amber-soft), transparent 240px), var(--ad-panel);
        border-right: 1px solid var(--ad-line);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-brand { gap: 14px; padding: 0 4px; }
      .kv-admin-shell.kv-admin-top .kv-admin-logo-icon {
        min-width: 36px; height: 36px; border-radius: 3px;
        background: var(--ad-amber); color: #10161A;
        clip-path: polygon(0 0, 100% 0, 100% 72%, 72% 100%, 0 100%);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-logo-icon svg { width: 19px; height: 19px; stroke-width: 2.2; }
      .kv-admin-shell.kv-admin-top .kv-admin-logo {
        padding: 0; font-family: 'JetBrains Mono', monospace;
        font-size: .74rem; font-weight: 600; letter-spacing: .01em; line-height: 1.35;
        text-transform: uppercase; color: var(--ad-text);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-logo span:last-child {
        display: block; color: var(--ad-amber); font-size: .6rem; letter-spacing: .24em;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-side-group { gap: 8px; }
      .kv-admin-shell.kv-admin-top .kv-admin-side-label {
        display: flex; align-items: center; gap: 8px; padding: 0 8px 2px;
        font-family: 'JetBrains Mono', monospace; font-size: .58rem; font-weight: 500;
        letter-spacing: .16em; color: var(--ad-dim); text-transform: uppercase;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-side-label::after { content: ''; height: 1px; flex: 1; background: var(--ad-line); }
      .kv-admin-shell.kv-admin-top .kv-admin-nav,
      .kv-admin-shell.kv-admin-top .kv-admin-side-quick { counter-reset: adx-nav; gap: 3px; }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item {
        counter-increment: adx-nav; position: relative; gap: 10px;
        min-height: 38px; padding: 8px 10px; border-radius: 2px;
        font-family: 'JetBrains Mono', monospace; font-size: .69rem; font-weight: 500;
        letter-spacing: .02em; color: var(--ad-muted);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item::before {
        content: counter(adx-nav, decimal-leading-zero); width: 19px; flex-shrink: 0;
        font-size: .57rem; color: var(--ad-dim);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item svg { width: 15px; height: 15px; }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item:hover {
        color: var(--ad-text); background: var(--ad-raised); transform: translateX(2px);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item.active {
        color: var(--ad-amber); background: linear-gradient(90deg, var(--ad-amber-soft), transparent 92%);
        box-shadow: inset 3px 0 0 var(--ad-amber); font-weight: 600; transform: none;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-nav .kv-admin-nav-item.active::before { color: var(--ad-amber); }
      .kv-admin-shell.kv-admin-top .kv-admin-nav-badge {
        min-width: 17px; height: 17px; border-radius: 2px; background: var(--ad-red);
        color: #140B0C; font-family: 'JetBrains Mono', monospace; font-size: .58rem;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-side-foot { gap: 8px; }
      .kv-admin-shell.kv-admin-top .kv-admin-quicklink {
        border: 1px solid var(--ad-line); border-radius: 2px; background: transparent;
        font-family: 'JetBrains Mono', monospace; font-size: .62rem;
        letter-spacing: .07em; text-transform: uppercase; color: var(--ad-muted);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-quicklink:hover {
        border-color: var(--ad-amber); background: var(--ad-amber-soft); color: var(--ad-amber);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-topbar-new {
        position: sticky; top: 0; z-index: 40; align-items: center; gap: 16px; padding: 12px 28px;
        background: var(--ad-panel); border-bottom: 1px solid var(--ad-line);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-topbar-new::after {
        content: ''; position: absolute; left: 0; bottom: -1px; width: 108px; height: 2px;
        background: linear-gradient(90deg, var(--ad-amber), var(--ad-teal));
      }
      .kv-admin-shell.kv-admin-top .kv-admin-crumb {
        flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px;
        font-family: 'JetBrains Mono', monospace; font-size: .62rem;
        letter-spacing: .14em; text-transform: uppercase; color: var(--ad-dim);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-crumb-current {
        color: var(--ad-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-bottom-nav { display: none; }
      @media (max-width: 1024px) {
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-nav {
          display: flex; flex-direction: column; gap: 6px;
          position: fixed; left: 50%; bottom: calc(10px + env(safe-area-inset-bottom, 0px)); z-index: 75;
          width: calc(100vw - 16px); max-width: 520px; padding: 12px 10px 8px;
          transform: translateX(-50%); border: 1px solid var(--ad-line); border-radius: 24px;
          background: var(--ad-panel); box-shadow: var(--ad-shadow);
        }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-primary {
          display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 2px;
        }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-extra {
          display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2px; justify-items: center;
          width: 100%; padding-top: 6px; border-top: 1px solid var(--ad-line);
        }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-expand {
          position: absolute; left: 50%; top: 0; z-index: 2;
          display: flex; align-items: center; gap: 4px; height: 24px; padding: 0 10px;
          transform: translate(-50%, -50%); border: 1px solid var(--ad-line); border-radius: 999px;
          background: var(--ad-panel); color: var(--ad-amber); cursor: pointer;
          font-family: 'JetBrains Mono', monospace; font-size: .55rem; font-weight: 700;
          letter-spacing: .08em; text-transform: uppercase;
        }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-expand svg { transition: transform .18s ease; }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-expand.expanded svg { transform: rotate(180deg); }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-item {
          min-width: 0; height: 46px; padding: 2px 0; border: 0; border-radius: 12px;
          background: transparent; color: var(--ad-muted); cursor: pointer; position: relative;
          display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
          transition: color .16s ease, background-color .16s ease;
        }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-item:hover { color: var(--ad-text); background: var(--ad-raised); }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-item.active { color: var(--ad-amber); background: var(--ad-amber-soft); }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-icon { display: inline-flex; color: inherit; }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-icon svg { width: 18px; height: 18px; }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-label { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 9.5px; font-weight: 600; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-bar { position: absolute; left: 50%; bottom: 1px; width: 14px; height: 2px; border-radius: 2px; background: var(--ad-amber); transform: translateX(-50%); }
        .kv-admin-shell.kv-admin-top .kv-admin-bottom-badge { position: absolute; top: 2px; right: calc(50% - 18px); min-width: 15px; height: 15px; padding: 0 4px; border-radius: 999px; display: grid; place-items: center; background: var(--ad-red); color: #140B0C; font-family: 'JetBrains Mono', monospace; font-size: .55rem; font-weight: 700; }
        .kv-admin-shell.kv-admin-top .kv-admin-content { padding-bottom: calc(132px + env(safe-area-inset-bottom, 0px)); }
        .kv-admin-shell.kv-admin-top.kv-admin-bottom-open .kv-admin-content { padding-bottom: calc(158px + env(safe-area-inset-bottom, 0px)); }
      }
      .kv-admin-shell.kv-admin-top .kv-admin-avatar {
        width: 32px; height: 32px; border-radius: 2px;
        clip-path: polygon(0 0, 100% 0, 100% 74%, 74% 100%, 0 100%);
        background: var(--ad-amber); color: #10161A;
        font-family: 'JetBrains Mono', monospace; font-size: .7rem; font-weight: 700;
      }
      .kv-admin-shell.kv-admin-top .kv-admin-main-full { max-width: 1440px; padding: 30px 34px 64px; }
      .kv-admin-shell.kv-admin-top .kv-admin-pagehead {
        position: relative; margin-bottom: 24px; padding-bottom: 18px;
        border-bottom: 1px solid var(--ad-line);
      }
      .kv-admin-shell.kv-admin-top .kv-admin-pagehead::after {
        content: ''; position: absolute; left: 0; bottom: -1px; width: 82px; height: 2px; background: var(--ad-amber);
