      .kv-admin-shell.kv-admin-top .kv-admin-chapter-empty { color: var(--ad-dim); font-family: 'JetBrains Mono', monospace; font-size: .7rem; }
      .kv-admin-shell.kv-admin-top .kv-mono { color: var(--ad-muted); }
      .kv-admin-shell.kv-admin-top .kv-admin-main-full > * { animation: adx-rise .4s ease backwards; }
      .kv-admin-shell.kv-admin-top .kv-admin-main-full > *:nth-child(2) { animation-delay: .06s; }
      .kv-admin-shell.kv-admin-top .kv-admin-main-full > *:nth-child(3) { animation-delay: .12s; }
      @keyframes adx-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      @keyframes adx-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
      @media (max-width: 1100px) {
        .kv-admin-shell.kv-admin-top .kv-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        .kv-admin-shell.kv-admin-top .kv-manga-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      }
