        .kv-admin-shell.kv-admin-top .kv-admin-topbar-new .kv-admin-top-actions { margin-left: auto; justify-content: flex-end; gap: 6px; flex-wrap: nowrap; white-space: nowrap; }
        .kv-admin-shell.kv-admin-top .kv-admin-main-full { padding: 22px 16px 52px; }
        .kv-admin-shell.kv-admin-top .kv-kpi-grid,
        .kv-admin-shell.kv-admin-top .kv-qa-grid,
        .kv-admin-shell.kv-admin-top .kv-form-grid,
