      body.kv-account-route .kv-acct-page { max-width: 1180px; margin: 0 auto; padding: 14px 16px 56px; font-family: 'Plus Jakarta Sans', Inter, system-ui, sans-serif; }
      body.kv-account-route .kv-acct-topline { height: 14px; margin: -14px -16px 22px; border-bottom: 1px solid var(--kv-acct-line); background: var(--kv-acct-canvas); }
      body.kv-account-route .kv-acct-plate { position: relative; overflow: hidden; border: 1px solid var(--kv-acct-line); border-radius: 18px; background: var(--kv-acct-panel); box-shadow: var(--kv-acct-shadow); animation: kv-acct-rise .34s ease both; }
      body.kv-account-route .kv-acct-plate::before { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 4px; background: var(--kv-acct-accent); z-index: 2; }
      body.kv-account-route .kv-acct-plate::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, var(--kv-acct-veil), transparent 78%); pointer-events: none; }
      body.kv-account-route .kv-acct-plate-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .72; }
      body.kv-account-route .kv-acct-plate-art-default { position: absolute; inset: 0; background: linear-gradient(120deg, var(--kv-acct-accent) 0%, var(--kv-acct-accent) 42%, var(--kv-acct-line) 100%); opacity: .7; }
      body.kv-account-route .kv-acct-plate-body { position: relative; z-index: 1; display: flex; align-items: center; gap: 18px; padding: 28px 30px 22px 34px; flex-wrap: wrap; }
      body.kv-account-route .kv-acct-avatar { width: 88px; height: 88px; flex: 0 0 88px; border-radius: 14px; overflow: hidden; border: 1px solid var(--kv-acct-line); background: var(--kv-acct-panel); display: grid; place-items: center; box-shadow: 0 12px 28px -20px rgba(0, 0, 0, .55); }
      body.kv-account-route .kv-acct-avatar img { width: 100%; height: 100%; object-fit: cover; display: block; }
      body.kv-account-route .kv-acct-avatar-fallback { font-family: 'JetBrains Mono', monospace; font-size: 2rem; font-weight: 700; color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-identity { flex: 1 1 260px; min-width: 0; }
      body.kv-account-route .kv-acct-eyebrow { display: block; font-family: 'JetBrains Mono', monospace; font-size: .64rem; letter-spacing: .12em; text-transform: uppercase; color: var(--kv-acct-accent); font-weight: 700; margin-bottom: 6px; }
      body.kv-account-route .kv-acct-name { margin: 0; font-size: clamp(1.5rem, 3vw, 2.05rem); line-height: 1.1; font-weight: 800; letter-spacing: -.02em; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-contact { margin-top: 6px; font-size: .84rem; font-weight: 600; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-subline { display: flex; align-items: center; gap: 8px; margin-top: 4px; font-size: .72rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--kv-acct-muted); opacity: .7; }
      body.kv-account-route .kv-acct-actions { display: flex; gap: 8px; flex-wrap: wrap; }
      body.kv-account-route .kv-acct-btn { appearance: none; border: 1px solid var(--kv-acct-line); border-radius: 12px; padding: 10px 14px; font-family: inherit; font-size: .76rem; font-weight: 700; cursor: pointer; transition: transform .16s ease, background .16s ease, border-color .16s ease, color .16s ease; }
      body.kv-account-route .kv-acct-btn:hover { transform: translateY(-1px); border-color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-btn-primary { background: var(--kv-acct-accent); border-color: var(--kv-acct-accent); color: #F7F1E6; }
      html.dark body.kv-account-route .kv-acct-btn-primary { color: #101014; }
      body.kv-account-route .kv-acct-btn-quiet { background: transparent; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-metrics { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid var(--kv-acct-line); }
      body.kv-account-route .kv-acct-metric { padding: 14px 18px 18px 34px; border-right: 1px solid var(--kv-acct-line); }
      body.kv-account-route .kv-acct-metric:last-child { border-right: 0; }
      body.kv-account-route .kv-acct-metric-label { display: block; font-family: 'JetBrains Mono', monospace; font-size: .6rem; letter-spacing: .1em; text-transform: uppercase; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-metric-value { display: block; margin-top: 4px; font-family: 'JetBrains Mono', monospace; font-size: 1.35rem; font-weight: 700; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-grid { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(260px, .85fr); gap: 18px; margin-top: 18px; align-items: start; }
      body.kv-account-route .kv-acct-main,
      body.kv-account-route .kv-acct-rail { display: flex; flex-direction: column; gap: 18px; }
      body.kv-account-route .kv-acct-sheet { border: 1px solid var(--kv-acct-line); border-radius: 18px; background: var(--kv-acct-panel); box-shadow: var(--kv-acct-shadow); overflow: hidden; animation: kv-acct-rise .36s ease both; }
      body.kv-account-route .kv-acct-main .kv-acct-sheet:nth-child(2),
      body.kv-account-route .kv-acct-rail .kv-acct-sheet:nth-child(2) { animation-delay: .06s; }
      body.kv-account-route .kv-acct-sheet-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--kv-acct-line); }
      body.kv-account-route .kv-acct-sheet-kicker { display: block; font-family: 'JetBrains Mono', monospace; font-size: .58rem; letter-spacing: .12em; text-transform: uppercase; color: var(--kv-acct-accent); font-weight: 700; }
      body.kv-account-route .kv-acct-sheet-title { margin: 2px 0 0; font-size: .95rem; font-weight: 800; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-sheet-meta { font-family: 'JetBrains Mono', monospace; font-size: .68rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-sheet-link { font-size: .72rem; font-weight: 700; color: var(--kv-acct-accent); text-decoration: none; display: inline-flex; gap: 5px; align-items: center; }
      body.kv-account-route .kv-acct-sheet-body { padding: 16px 18px; }
      body.kv-account-route .kv-acct-history { display: flex; flex-direction: column; gap: 10px; }
      body.kv-account-route .kv-acct-history-row { display: flex; align-items: center; gap: 12px; padding: 10px; border: 1px solid var(--kv-acct-line); border-radius: 14px; background: var(--kv-acct-canvas); transition: transform .18s ease, border-color .18s ease; }
      body.kv-account-route .kv-acct-history-row:hover { transform: translateX(3px); border-color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-history-cover { width: 52px; height: 68px; flex: 0 0 52px; border-radius: 9px; overflow: hidden; background: var(--kv-acct-panel); border: 1px solid var(--kv-acct-line); }
      body.kv-account-route .kv-acct-history-cover img { width: 100%; height: 100%; object-fit: cover; display: block; }
      body.kv-account-route .kv-acct-history-copy { flex: 1; min-width: 0; }
      body.kv-account-route .kv-acct-history-kicker { font-family: 'JetBrains Mono', monospace; font-size: .58rem; letter-spacing: .08em; text-transform: uppercase; color: var(--kv-acct-accent); font-weight: 700; }
      body.kv-account-route .kv-acct-history-title { margin: 3px 0; font-size: .84rem; font-weight: 700; color: var(--kv-acct-ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      body.kv-account-route .kv-acct-history-sub { font-size: .68rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-history-go { flex: 0 0 auto; border: 1px solid var(--kv-acct-accent); border-radius: 10px; padding: 7px 10px; font-size: .68rem; font-weight: 700; color: var(--kv-acct-accent); text-decoration: none; display: inline-flex; align-items: center; gap: 5px; }
      body.kv-account-route .kv-acct-history-go:hover { background: var(--kv-acct-accent); color: var(--kv-acct-canvas); }
      body.kv-account-route .kv-acct-bookmarks { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
      body.kv-account-route .kv-acct-bookmarks .kv-home-card { background: var(--kv-acct-canvas); border-color: var(--kv-acct-line); border-radius: 12px; padding: 8px; }
      body.kv-account-route .kv-acct-bookmarks .kv-home-card-cover { background: var(--kv-acct-panel); }
      body.kv-account-route .kv-acct-empty { margin: 0; padding: 18px; border: 1px dashed var(--kv-acct-line); border-radius: 12px; font-size: .8rem; color: var(--kv-acct-muted); text-align: center; }
      body.kv-account-route .kv-acct-pref { display: flex; align-items: center; gap: 10px; padding: 11px; border: 1px solid var(--kv-acct-line); border-radius: 12px; background: var(--kv-acct-canvas); }
      body.kv-account-route .kv-acct-pref-icon { width: 34px; height: 34px; flex: 0 0 34px; border-radius: 10px; display: grid; place-items: center; background: var(--kv-acct-panel); border: 1px solid var(--kv-acct-line); font-family: 'JetBrains Mono', monospace; font-size: .7rem; font-weight: 700; color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-pref-copy { flex: 1; display: grid; gap: 2px; }
      body.kv-account-route .kv-acct-pref-copy strong { font-size: .78rem; color: var(--kv-acct-ink); }
      body.kv-account-route .kv-acct-pref-copy span { font-size: .68rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-chip { border: 1px solid var(--kv-acct-line); border-radius: 9px; padding: 6px 9px; background: var(--kv-acct-panel); color: var(--kv-acct-accent); font-family: inherit; font-size: .68rem; font-weight: 700; cursor: pointer; }
      body.kv-account-route .kv-acct-links { display: flex; flex-direction: column; gap: 6px; }
      body.kv-account-route .kv-acct-link { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border-radius: 10px; background: var(--kv-acct-canvas); border: 1px solid var(--kv-acct-line); color: var(--kv-acct-ink); text-decoration: none; font-size: .76rem; font-weight: 700; }
      body.kv-account-route .kv-acct-link:hover { border-color: var(--kv-acct-accent); color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-danger { width: 100%; border: 1px solid var(--kv-acct-line); border-radius: 14px; padding: 11px; background: transparent; color: var(--kv-acct-muted); font-family: inherit; font-size: .74rem; font-weight: 700; cursor: pointer; }
      body.kv-account-route .kv-acct-danger:hover { border-color: #B45353; color: #B45353; }
      html.dark body.kv-account-route .kv-acct-danger:hover { color: #F87171; }
      body.kv-account-route .kv-acct-edit { margin-top: 18px; border: 1px solid var(--kv-acct-line); border-radius: 18px; background: var(--kv-acct-panel); box-shadow: var(--kv-acct-shadow); animation: kv-acct-rise .34s ease both; }
      body.kv-account-route .kv-acct-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; padding: 16px 18px 0; }
      body.kv-account-route .kv-acct-field { display: grid; gap: 6px; font-family: 'JetBrains Mono', monospace; font-size: .6rem; letter-spacing: .1em; text-transform: uppercase; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-field:nth-child(3),
      body.kv-account-route .kv-acct-field:nth-child(4) { grid-column: 1 / -1; }
      body.kv-account-route .kv-acct-field input { width: 100%; border: 1px solid var(--kv-acct-line); border-radius: 10px; background: var(--kv-acct-canvas); color: var(--kv-acct-ink); padding: 9px 11px; font-family: 'Plus Jakarta Sans', sans-serif; font-size: .8rem; letter-spacing: normal; text-transform: none; }
      body.kv-account-route .kv-acct-field input:focus { outline: none; border-color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-text-btn { border: 0; background: transparent; color: var(--kv-acct-muted); font-family: inherit; font-size: .72rem; font-weight: 700; cursor: pointer; }
      body.kv-account-route .kv-acct-note { margin: 12px 18px 0; font-size: .7rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-edit-actions { display: flex; justify-content: flex-end; padding: 14px 18px 18px; }
      body.kv-account-route .kv-acct-guest-wrap { display: grid; place-items: center; min-height: calc(100vh - 190px); }
      body.kv-account-route .kv-acct-guest-sheet { width: min(100%, 560px); border: 1px solid var(--kv-acct-line); border-radius: 18px; background: var(--kv-acct-panel); box-shadow: var(--kv-acct-shadow); overflow: hidden; animation: kv-acct-rise .36s ease both; }
      body.kv-account-route .kv-acct-guest-brand { display: grid; place-items: center; min-height: 104px; border-bottom: 1px solid var(--kv-acct-line); background: linear-gradient(135deg, var(--kv-acct-accent), var(--kv-acct-line)); }
      body.kv-account-route .kv-acct-guest-logo { max-width: 180px; max-height: 56px; }
      body.kv-account-route .kv-acct-guest-logo img { max-width: 100%; max-height: 56px; object-fit: contain; display: block; }
      body.kv-account-route .kv-acct-guest-mark { font-family: 'JetBrains Mono', monospace; font-size: 1.6rem; font-weight: 800; letter-spacing: .12em; color: #F7F1E6; }
