      body.kv-account-route .kv-acct-guest-providers > p { margin: 0; font-size: .78rem; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn { background: var(--kv-acct-canvas); border-color: var(--kv-acct-line); color: var(--kv-acct-ink); box-shadow: none; }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn:hover { background: var(--kv-acct-accent); border-color: var(--kv-acct-accent); color: #F7F1E6; transform: translateY(-1px); }
      html.dark body.kv-account-route .kv-acct-guest-providers .kv-login-btn:hover { color: #101014; }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn-icon { background: var(--kv-acct-panel); border-color: var(--kv-acct-line); }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn-text small { color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn-arrow { color: var(--kv-acct-accent); }
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn:hover .kv-login-btn-arrow,
      body.kv-account-route .kv-acct-guest-providers .kv-login-btn:hover .kv-login-btn-text small { color: inherit; }
      body.kv-account-route .kv-acct-guest-note { margin: 18px 0 0; padding-top: 14px; border-top: 1px solid var(--kv-acct-line); font-size: .7rem; line-height: 1.55; color: var(--kv-acct-muted); }
      body.kv-account-route .kv-acct-guest-note strong { color: var(--kv-acct-accent); }
      @keyframes kv-acct-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      @media (max-width: 900px) {
        body.kv-account-route .kv-acct-grid { grid-template-columns: 1fr; }
        body.kv-account-route .kv-acct-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        body.kv-account-route .kv-acct-metric:nth-child(2) { border-right: 0; }
        body.kv-account-route .kv-acct-metric:nth-child(-n+2) { border-bottom: 1px solid var(--kv-acct-line); }
      }
      @media (max-width: 560px) {
