            :root {
        --background: var(--kv-bg);
        --foreground: var(--kv-text);
        --card: var(--kv-surface);
        --card-foreground: var(--kv-text);
        --primary: var(--kv-accent);
        --primary-foreground: #FFFFFF;
        --secondary: var(--kv-surface-2);
        --muted: var(--kv-surface-2);
        --muted-foreground: var(--kv-text-muted);
        --border: var(--kv-border);
        --accent: var(--kv-neon);
        --accent-foreground: #FFFFFF;
        --input: var(--kv-surface-2);
        --ring: var(--kv-accent);
      }
      html {
        transition: background-color .24s ease, color .24s ease;
      }
      body, header, nav, aside, .kv-card, .kv-btn, .kv-input, .kv-theme-menu-inline, .kv-theme-choice {
        transition: background-color .24s ease, border-color .24s ease, color .24s ease, box-shadow .24s ease;
      }
      .kv-theme-menu-inline {
        display: flex; align-items: center; gap: 4px; flex-wrap: wrap;
        padding: 6px; border-radius: 14px;
        border: 1px solid var(--kv-border); background: var(--kv-surface);
        box-shadow: 0 16px 38px -26px rgba(0,0,0,.55);
      }
      .kv-theme-menu-inline.is-compact { gap: 2px; padding: 4px; border-radius: 10px; }
      .kv-theme-menu-inline.is-compact .kv-theme-choice { width: 24px; height: 24px; border-radius: 7px; }
      .kv-theme-menu-inline.is-compact .kv-theme-choice svg { width: 12px; height: 12px; }
      .kv-theme-menu-inline.is-compact .kv-theme-choice::after { display: none; }
      .kv-theme-choice {
        position: relative; width: 30px; height: 30px; padding: 0;
        display: inline-flex; align-items: center; justify-content: center;
        border: 1px solid transparent; border-radius: 9px;
        background: transparent; color: var(--kv-text-muted); cursor: pointer;
      }
      .kv-theme-choice svg { width: 15px; height: 15px; display: block; }
      .kv-theme-choice:hover, .kv-theme-choice:focus-visible { color: var(--kv-text); background: var(--kv-surface-2); outline: none; }
      .kv-theme-choice[data-current="true"] {
        color: var(--kv-accent); background: var(--kv-surface-2); border-color: var(--kv-border);
        box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--kv-accent) 35%, transparent);
      }
      .kv-theme-choice::after {
        content: attr(title); position: absolute; left: 50%; top: calc(100% + 7px);
        transform: translateX(-50%) translateY(-3px); z-index: 95;
        padding: 4px 7px; border-radius: 6px; white-space: nowrap;
        background: var(--kv-text); color: var(--kv-surface);
        font-family: var(--kv-font-mono); font-size: 8px; font-weight: 700; letter-spacing: .08em;
        opacity: 0; pointer-events: none; transition: opacity .16s ease, transform .16s ease;
      }
      .kv-theme-choice:hover::after, .kv-theme-choice:focus-visible::after { opacity: 1; transform: translateX(-50%) translateY(0); }
      .kv-reader-sheet .kv-theme-menu-inline { padding: 4px; background: var(--kv-surface-2); border-color: var(--kv-border); }
      .kv-admin-topbar .kv-theme-menu-inline { background: var(--ad-panel); border-color: var(--ad-line); }
      .kv-admin-topbar .kv-theme-choice { color: var(--ad-muted); }
      .kv-admin-topbar .kv-theme-choice[data-current="true"] { color: var(--ad-teal); background: var(--ad-raised); border-color: var(--ad-line); }
      html[data-theme="anilist"] {
        --background: #0F1014 !important; --foreground: #E9EEF7 !important;
        --card: #1A1C25 !important; --card-foreground: #E9EEF7 !important;
        --primary: #02A9FF !important; --primary-foreground: #05121C !important;
        --secondary: #242838 !important; --muted: #242838 !important;
        --muted-foreground: #A3B1C6 !important; --border: #2F3546 !important;
