        --kv-acct-panel-2: var(--secondary) !important;
        --kv-acct-line: var(--border) !important;
        --kv-acct-ink: var(--foreground) !important;
        --kv-acct-muted: var(--muted-foreground) !important;
        --kv-acct-accent: var(--primary) !important;
        --kv-acct-accent-hover: var(--ring) !important;
