        --kv-notif-canvas: var(--background) !important;
        --kv-notif-panel: var(--card) !important;
        --kv-notif-panel-2: var(--secondary) !important;
        --kv-notif-line: var(--border) !important;
        --kv-notif-ink: var(--foreground) !important;
        --kv-notif-muted: var(--muted-foreground) !important;
        --kv-notif-accent: var(--primary) !important;
        --kv-notif-stamp: var(--muted) !important;
