      }
      html[data-theme="anilist"] body, html[data-theme="catppuccin"] body, html[data-theme="mecha"] body { background: var(--background) !important; color: var(--foreground) !important; }
      html[data-theme="anilist"] [class*="bg-[#"], html[data-theme="catppuccin"] [class*="bg-[#"], html[data-theme="mecha"] [class*="bg-[#"] { background-color: var(--secondary) !important; background-image: none !important; }
      html[data-theme="anilist"] [class*="text-[#"], html[data-theme="catppuccin"] [class*="text-[#"], html[data-theme="mecha"] [class*="text-[#"], html[data-theme="anilist"] [class*="text-neutral"], html[data-theme="catppuccin"] [class*="text-neutral"], html[data-theme="mecha"] [class*="text-neutral"] { color: var(--foreground) !important; }
      html[data-theme="anilist"] [class*="border-[#"], html[data-theme="catppuccin"] [class*="border-[#"], html[data-theme="mecha"] [class*="border-[#"] { border-color: var(--border) !important; }
      html[data-theme="anilist"] [class*="placeholder-[#"]::placeholder, html[data-theme="catppuccin"] [class*="placeholder-[#"]::placeholder, html[data-theme="mecha"] [class*="placeholder-[#"]::placeholder { color: var(--muted-foreground) !important; }
      html[data-theme="anilist"] [class*="ring-[#"], html[data-theme="catppuccin"] [class*="ring-[#"], html[data-theme="mecha"] [class*="ring-[#"] { --tw-ring-color: var(--ring) !important; }
      html[data-theme="anilist"] [class*="from-[#"], html[data-theme="catppuccin"] [class*="from-[#"], html[data-theme="mecha"] [class*="from-[#"] { background-image: linear-gradient(90deg, var(--primary), var(--ring)) !important; }
      html[data-theme="anilist"] [class*="text-white"], html[data-theme="catppuccin"] [class*="text-white"], html[data-theme="mecha"] [class*="text-white"] { color: var(--primary-foreground) !important; }
      @media (max-width: 640px) {
        .kv-theme-choice { width: 32px; height: 32px; }
      }

body.script:
//
(function () {
  'use strict';

  /* =========================================================================
     UBAH KONFIGURASI DI SINI SEBELUM MEMASANG DI BLOGGER
     CATATAN KEAMANAN: Jangan pernah menaruh secret OAuth atau token bot
     Telegram di dalam file XML ini. Gunakan environment Vercel.
     ========================================================================= */
  /* =========================================================================
     ARSITEKTUR & INTEGRASI (DOKUMENTASI - BACA SEBELUM DEPLOY)
     =========================================================================
     KOMPONEN:
     1. BLOGGER (frontend): file XML ini. Menayangkan SPA pembaca. Blogger TIDAK
        bisa menjalankan kode server - semua rahasia HARUS di environment Vercel.
     2. VERCEL FUNCTIONS (folder proyek: api/) menyimpan secrets:
         DATABASE_URL, TELEGRAM_BOT_TOKEN, TELEGRAM_STORAGE_CHAT_ID,
         TOKEN_SECRET, PUBLIC_API_URL, ALLOWED_ORIGINS,
         dan credential OAuth Google/Discord.
         Backend ini memakai Neon Postgres untuk katalog/akun/komentar,
         dan Telegram hanya untuk penyimpanan gambar.
        Pemetaan ke tema Blogger:
        - CONFIG.API_BASE_URL  = PUBLIC_API_URL  (origin Vercel yang sama)
        - return_to OAuth      = origin blog      (harus terdaftar di ALLOWED_ORIGINS)
        Endpoint minimum yang dipanggil frontend:
        - GET  /api/auth/{google|discord}/start dan /callback -> login OAuth
        - GET  /api/auth/me                -> profil dan role sesi aktif
        - GET  /api/catalog               -> { manga, chapters, comments, reactions, mangaReactions }
        - POST /api/admin/upload-dual     -> simpan ke Telegram dan kembalikan
                                             URL proxy /api/media/{file_id}
        - POST /api/comment               -> { mangaId, content, ... } (menunggu moderasi)
        - POST /api/chapter/reaction      -> { chapterId, reaction }
        - POST /api/comment/upvote        -> { id }
        - POST /api/admin/save-manga      -> simpan/ubah data manga
        - POST /api/admin/save-chapter    -> simpan/ubah data chapter
        - POST /api/admin/delete-manga    -> { id }
        - POST /api/admin/delete-chapter  -> { id }
        - POST /api/admin/delete-comment  -> { id }
        - POST /api/admin/comment-status  -> { id, status }
        - POST /api/admin/pin-comment     -> { id } — sematkan komentar (admin)
        Semua endpoint admin memverifikasi header: Authorization: Bearer <token>.
     3. NEON POSTGRES menjadi database katalog/akun/komentar: archive
        disimpan sebagai dokumen JSONB pada tabel nexamanga_snapshot di
        database Neon (DATABASE_URL). Gambar tersimpan sebagai dokumen
        di chat Telegram; backend mem-proxy
        gambar lewat /api/media/{file_id}. Bot token dan connection string
        Neon tidak dikirim ke browser.
     BATASAN:
     - Snapshot disimpan sebagai dokumen JSONB di Neon (limit praktis 50 MiB),
        diperbarui dengan optimistic concurrency control (kolom version).
     - Tabel nexamanga_snapshot dibuat otomatis pada request pertama.
     - Gunakan satu sesi admin untuk mencegah perubahan serentak saling menimpa.
     - Upload JPEG/PNG/WebP maksimal 3 MiB per berkas (batas request Vercel).
      CATATAN JUJUR:
      - Backend wajib; API_BASE_URL harus diisi dan tidak boleh kosong.
      - Panduan deploy Vercel ada di README.md.
      - Notifikasi chapter baru butuh backend (mis. polling feed / bot
         broadcast ke channel) - tidak mungkin dari Blogger saja.
      - Akun lintas perangkat butuh backend; cache hanya untuk pembacaan offline.
      - Jangan unggah manga berhak cipta tanpa izin pemilik.
     ========================================================================= */
   var CONFIG = {
     SITE_NAME: '',                 /* Diisi dari Pengaturan Admin */
     SITE_TAGLINE: '',
      /* Cara tercepat: edit langsung nilai API_BASE_URL di bawah ini (Tema > Edit HTML).
        Harus identik dengan PUBLIC_API_URL di .env / Vercel Environment Variables.
        Katalog dan penulisan data tidak berfungsi tanpa backend. */
    API_BASE_URL: 'https://nexamanga-nexamanga.vercel.app',
    DEFAULT_THEME: 'system',
    THEME_IDS: ['system', 'light', 'anilist', 'catppuccin', 'mecha', 'dark'],
    THEME_META: { light: '#F7F1E6', dark: '#0B0E17', anilist: '#0F1014', catppuccin: '#1E1E2E', mecha: '#080C10' },
    ITEMS_PER_PAGE: 8,
     CONTACT_EMAIL: '' /* Diisi dari Pengaturan Admin */
  };

  /* =========================================================================
     STATE & PENGATURAN LOKAL NON-KATALOG
     ========================================================================= */
  var state = {
    route: 'home',
    params: {},
     theme: (function () { var v = localStorage.getItem('kv_theme') || CONFIG.DEFAULT_THEME; return CONFIG.THEME_IDS.indexOf(v) !== -1 ? v : CONFIG.DEFAULT_THEME; })(),
     imageCompressionEnabled: localStorage.getItem('kv_img_compress_enabled') !== '0',
     imageCompressionQuality: (function () { if (localStorage.getItem('kv_img_compress_ver') !== '3') { localStorage.setItem('kv_img_compress_ver', '3'); localStorage.setItem('kv_img_compress_quality', '0.95'); localStorage.setItem('kv_img_compress_maxdim', '4000'); if (localStorage.getItem('kv_img_compress_enabled') === null) localStorage.setItem('kv_img_compress_enabled', '1'); return 0.95; } return parseFloat(localStorage.getItem('kv_img_compress_quality') || '0.95') || 0.95; })(),
     imageCompressionMaxDim: (function () { if (localStorage.getItem('kv_img_compress_ver') !== '3') return 4000; return parseInt(localStorage.getItem('kv_img_compress_maxdim') || '4000', 10) || 4000; })(),

      /* Data dimuat dari: backend API -> snapshot cache */
      data: readCachedCatalog(),
     loading: false,
     error: null,
     sessionNotice: '',
     catalogNotice: '',
    search: '',
    filterGenres: [],
    filterStatus: 'Semua',
    filterType: 'Semua',
    filterMinChapters: 0,
    sortBy: 'terbaru',
    openCatalogDropdown: null,
    filterDrawerOpen: false,
    filterDrawerSkipAnim: false,
    page: 1,
    homePage: 1,
     chapterSortAsc: false,
     chapterSearch: '',
    readerMode: 'vertical', // 'vertical' | 'paged'
    readerWidth: 760,
    readerDir: 'ltr', // 'ltr' | 'rtl'
    currentPageIdx: 0,
     readerMenuOpen: false,
    readerControlsHidden: false,
     readerChapterSearch: '',
     readerChapterSearchRefocus: false,

    readerSettingsOpen: false,
     autoScroll: false,
     autoScrollSpeed: 2.5,

    readerDockTimer: null,
    user: null,
    bookmarks: JSON.parse(localStorage.getItem('kv_bookmarks') || '[]'),
    history: JSON.parse(localStorage.getItem('kv_history') || '[]'),
    adminToken: localStorage.getItem('kv_session_token') || '',
    refocusSearch: false,
    /* --- State panel admin & moderasi --- */
    adminTab: 'dashboard',
    adminForm: null,            // form manga aktif (objek) atau null = daftar
    adminChapterForm: null,     // form chapter aktif (objek) atau null
     adminChapterMangaId: '',
     adminRoleMenuOpen: null,
     adminChapterFullId: null,

    adminSearch: '',
    adminRefocusSearch: false,
     adminExpandedManga: null,
     uploadProgress: null,
       analyticsData: undefined,
       trafficTooltipRows: [],


     mdUrl: '',
     mdLang: 'en',
     mdLangMenuOpen: false,
     mdQuery: '',
     mdResults: [],
     mdLoading: false,
     mdError: '',
     mdImporting: false,
     mdProgress: null,
      analyticsFrom: '',
      analyticsTo: '',
      analyticsDefaultKey: '',
      analyticsUserChanged: false,
      analyticsError: '',
      analyticsRequestId: 0,


     commentFilter: 'Semua',
     commentSort: 'newest',

    commentNotice: '',
     pendingDelete: null,        // { type, id, label, confirmLabel }
     toasts: [],
      usersCache: undefined,
      adminDrawerOpen: false,
      adminBottomExpanded: false,
      editingProfile: false,
      replyingTo: null,
      imageTargetForm: null,
      commentImageIndex: 0,
      commentImageMap: {},
      viewedChapters: {}
    };

  function readCachedCatalog() {
    try {
      var value = JSON.parse(localStorage.getItem('kv_catalog_snapshot') || 'null');
      if (value && Array.isArray(value.manga) && Array.isArray(value.chapters) && Array.isArray(value.comments)) return value;
    } catch (e) {}
    return { manga: [], chapters: [], comments: [] };
  }

  function decodeSessionClaims(token) {
    if (!token || typeof token !== 'string') return null;
    var parts = token.split('.');
    if (parts.length !== 2) return null;
    try {
      var encoded = parts[0].replace(/-/g, '+').replace(/_/g, '/');
      while (encoded.length % 4) encoded += '=';
      return JSON.parse(decodeURIComponent(escape(window.atob(encoded))));
    } catch (e) { return null; }
  }

  function isSessionUnauthorized(response) {
    return !!response && response.status === 401 &&
      !!response.headers && typeof response.headers.get === 'function' &&
      response.headers.get('x-nexamanga-auth') === '1';
  }

  function restoreSessionFromCache(claims) {
    if (!claims || !claims.sub) return null;
    try {
      var cached = JSON.parse(localStorage.getItem('kv_session_cache_v1') || 'null');
      if (cached && cached.id === claims.sub && cached.user && cached.user.id === claims.sub) return cached.user;
    } catch (e) {}
    if (claims.user && claims.user.id === claims.sub) return claims.user;
    return null;
  }

  function saveSessionCache(user) {
    if (!user || !user.id) return;
    try { localStorage.setItem('kv_session_cache_v1', JSON.stringify({ id: user.id, user: user, savedAt: Date.now() })); } catch (e) {}
  }

  function clearSession() {
    state.user = null;
    state.adminToken = '';
    state.usersCache = undefined;
    localStorage.removeItem('kv_session_token');
    localStorage.removeItem('kv_session_cache_v1');
  }

  function clearProfileOverrides() {
    try {
      var doomed = [];
      for (var i = 0; i < localStorage.length; i++) {
        var key = localStorage.key(i);
        if (key && key.indexOf('kv_profile_override_v2_') === 0) doomed.push(key);
      }
      doomed.forEach(function (key) { localStorage.removeItem(key); });
    } catch (e) {}
  }

  function uid(prefix) {
    return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);
  }

  function slugify(text) {
    return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }

  function today() {
    return new Date().toISOString().slice(0, 10);
  }
  function localIsoDate(date) {
    var d = date instanceof Date ? date : new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  function analyticsDefaultRange() {
    var now = new Date();
    return {
      from: now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-01',
      to: localIsoDate(now)
    };
  }
  function syncAnalyticsDefaultRange() {
    var def = analyticsDefaultRange();
    var key = def.from + '|' + def.to;
    if (state.analyticsDefaultKey !== key) {
      state.analyticsDefaultKey = key;
      state.analyticsFrom = def.from;
      state.analyticsTo = def.to;
      state.analyticsUserChanged = false;
      state.analyticsData = undefined;
    } else if (!state.analyticsUserChanged) {
      if (!state.analyticsFrom) state.analyticsFrom = def.from;
      if (!state.analyticsTo) state.analyticsTo = def.to;
    }
    return def;
  }
  function refreshAnalyticsPeriodIfNeeded() {
    var before = state.analyticsDefaultKey;
    syncAnalyticsDefaultRange();
    if (state.analyticsDefaultKey !== before && state.adminTab === 'analytics') render();
  }
  function dateFromKey(key) {
    var m = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!m) return null;
    var d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    return isNaN(d.getTime()) ? null : d;
  }
  function parseDateKey(value) {
    var raw = String(value || '').trim();
    var m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return m[0];
    var d = new Date(raw);
    return isNaN(d.getTime()) ? '' : localIsoDate(d);
  }
  function fullDateLabel(key) {
    var d = dateFromKey(key);
    if (!d) return String(key || '-');
    try {
      return new Intl.DateTimeFormat('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(d);
    } catch (e) {
      return localIsoDate(d);
    }
  }
  function shortDateLabel(key) {
    var d = dateFromKey(key);
    if (!d) return String(key || '-');
    return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0');
  }
  function buildDailySeries(rows, from, to) {
    var start = dateFromKey(from);
    var end = dateFromKey(to);
    if (!start || !end || start > end) return [];
    var map = {};
    (rows || []).forEach(function (r) {
      var key = parseDateKey(r.date || r.day || '');
      if (!key) return;
      map[key] = {
        date: key,
        pageviews: Number(r.pageviews) || 0,
        visitors: Number(r.visitors) || 0,
        visits: Number(r.visits) || 0
      };
    });
    var out = [];
    var cur = new Date(start.getTime());
    var guard = 0;
    while (cur <= end && guard < 3660) {
      var key = localIsoDate(cur);
      var row = map[key] || {};
      out.push({
        date: key,
        pageviews: row.pageviews || 0,
        visitors: row.visitors || 0,
        visits: row.visits || 0
      });
      cur.setDate(cur.getDate() + 1);
      guard++;
    }
    return out;
  }
  function changeLabel(prev, curr) {
    if (prev === null || prev === undefined) return '-';
    if (prev === 0) return curr === 0 ? '0%' : '-';
    var pct = Math.round(((curr - prev) / prev) * 100);
    return (pct > 0 ? '+' : '') + pct + '%';
  }

   function siteSetting(key, fallback) {
     var settings = (state.data && state.data.settings) ? state.data.settings : {};
     if (settings && settings[key]) return settings[key];
     return fallback;
   }

    function siteName() { return String(siteSetting('siteName', CONFIG.SITE_NAME) || '').trim(); }
    function siteTagline() { return String(siteSetting('siteTagline', CONFIG.SITE_TAGLINE) || '').trim(); }
    function siteLabel() { return siteName() || 'Situs'; }
    function siteLogo() { return siteSetting('logoUrl', ''); }
    function siteFavicon() { return siteSetting('faviconUrl', ''); }
    function applyFavicon() {
      var link = document.getElementById('kv-dynamic-favicon');
      var url = siteFavicon();
      if (!url) {
        if (link && link.parentNode) link.parentNode.removeChild(link);
        return;
      }
      if (!link) {
        link = document.createElement('link');
        link.id = 'kv-dynamic-favicon';
        link.rel = 'icon';
        document.head.appendChild(link);
      }
      if (link.getAttribute('href') !== url) link.setAttribute('href', url);
      var type = /\.svg(?:\?|$)/i.test(url) ? 'image/svg+xml' : /\.png(?:\?|$)/i.test(url) ? 'image/png' : /\.ico(?:\?|$)/i.test(url) ? 'image/x-icon' : '';
      if (type) link.setAttribute('type', type); else link.removeAttribute('type');
    }
     function siteContact() { return String(siteSetting('contactEmail', CONFIG.CONTACT_EMAIL) || '').trim(); }
   function brandMode() { return siteSetting('brandMode', 'logo-name'); }
    function siteNameColor() { return siteSetting('siteNameColor', ''); }
    function siteNameStyle() { var c = siteNameColor(); return c ? ' style="color:' + escapeHtml(c) + '"' : ''; }
    function normalizeHexColor(value) {
      var color = String(value || '').trim().toLowerCase();
      if (/^#[0-9a-f]{3}$/.test(color)) {
        return '#' + color.slice(1).split('').map(function (char) { return char + char; }).join('');
      }
      return /^#[0-9a-f]{6}$/.test(color) ? color : '';
    }
    function colorStudioHtml(value) {
      var hex = normalizeHexColor(value);
      var effective = hex || '#6366F1';
      var presets = ['#F2A93B', '#FF5B4A', '#48D7B6', '#E85D9E', '#4F7CAC', '#2F80ED', '#8A560C', '#121820'];
      return '<div class="kv-color-studio" data-color-studio>' +
        '<div class="kv-color-studio-head">' +
          '<div><div class="kv-color-studio-title">Warna Nama Situs</div></div>' +
        '</div>' +
        '<div class="kv-color-studio-controls">' +
          '<label class="kv-color-field-label">Warna Pilihan' +
            '<div class="kv-color-row">' +
              '<input class="kv-input kv-color-native" name="siteNameColor" type="color" value="' + effective + '" aria-label="Pilih warna nama situs"/>' +
              '<input class="kv-input kv-color-hex" type="text" value="' + (hex ? hex.toUpperCase() : '') + '" placeholder="#F2A93B" maxlength="7" spellcheck="false" autocomplete="off" aria-label="Kode warna hex"/>' +
            '</div>' +
          '</label>' +
          '<div class="kv-color-field-label">Preset Cepat' +
            '<div class="kv-color-presets">' + presets.map(function (color) {
              return '<button type="button" class="kv-color-preset' + (color === hex ? ' is-active' : '') + '" data-color="' + color + '" style="--preset:' + color + '" title="' + color + '" aria-label="Gunakan ' + color + '"></button>';
            }).join('') + '</div>' +
          '</div>' +
        '</div>' +
      '</div>';
    }
    function bindColorStudio(form, studio) {
      var native = form.querySelector('input[name="siteNameColor"]');
      var hex = studio.querySelector('.kv-color-hex');
      var presets = Array.prototype.slice.call(studio.querySelectorAll('.kv-color-preset'));
      function applyColor(value, preserveInput) {
        var normalized = normalizeHexColor(value);
        var raw = String(value || '').trim();
        if (hex) {
          if (normalized) hex.value = normalized.toUpperCase();
          else if (!preserveInput) hex.value = '';
          hex.classList.toggle('is-invalid', !!raw && !normalized);
        }
        if (native) native.value = normalized || '#6366F1';
        presets.forEach(function (button) {
          button.classList.toggle('is-active', button.getAttribute('data-color') === normalized);
        });
      }
      if (native) native.addEventListener('input', function () { applyColor(native.value, false); });
      if (hex) {
        hex.addEventListener('input', function () { applyColor(hex.value, true); });
        hex.addEventListener('blur', function () { applyColor(hex.value, false); });
      }
      presets.forEach(function (button) {
        button.addEventListener('click', function () { applyColor(button.getAttribute('data-color'), false); });
      });
      applyColor(hex ? hex.value : native ? native.value : '', false);
    }

    function mangaById(id) {
     return state.data.manga.filter(function (m) { return m.id === id; })[0] || null;
   }

     function normalizeReactionSummary(entry) {
       var keys = ['fire', 'shock', 'cry', 'laugh', 'angry'];
       var counts = {};
       var userVote = null;
       for (var i = 0; i < keys.length; i++) {
         if (entry && entry.counts && typeof entry.counts === 'object') {
           counts[keys[i]] = Number(entry.counts[keys[i]]) || 0;
         } else {
           var list = entry && Array.isArray(entry[keys[i]]) ? entry[keys[i]] : [];
           counts[keys[i]] = list.length;
         }
         if (entry && entry.userVote === keys[i]) userVote = keys[i];
       }
       return { counts: counts, userVote: userVote };
     }

    function purgeLegacyProfileOverrides() {
      try {
        if (localStorage.getItem('kv_pov_purged') === '2') return;
        var doomed = [];
        for (var i = 0; i < localStorage.length; i++) {
          var key = localStorage.key(i);
          if (!key) continue;
          var isLegacyGlobal = key === 'kv_profile_override';
          var isOldPerUser = key.indexOf('kv_profile_override_') === 0 && key.indexOf('kv_profile_override_v2_') !== 0;
          if (isLegacyGlobal || isOldPerUser) doomed.push(key);
        }
        doomed.forEach(function (key) { localStorage.removeItem(key); });
        localStorage.setItem('kv_pov_purged', '2');
      } catch (e) { /* abaikan */ }
    }

    function profileOverride() {
      var id = state.user && state.user.id;
      if (!id) return {};
      try { return JSON.parse(localStorage.getItem('kv_profile_override_v2_' + id) || '{}') || {}; } catch (e) { return {}; }
    }

    function currentDisplayName(fallback) {
      var o = profileOverride();
      return o.name || (state.user && state.user.name) || fallback || 'Pengguna';
    }

    function currentDisplayAvatar(fallback) {
      var o = profileOverride();
      if (o.avatar) return o.avatar;
      if (state.user && state.user.avatar) return state.user.avatar;
      return fallback || null;
    }

    function currentDisplayBackground(fallback) {
      var o = profileOverride();
      if (o.background) return o.background;
      return fallback || null;
    }

    function replaceImageTokens(content) {
      var map = state.commentImageMap || {};
      Object.keys(map).forEach(function (token) {
        var url = map[token];
        var md = '![gambar](' + url + ')';
        content = content.split(token).join(md);
      });
      state.commentImageMap = {};
      return content;
    }

   function chapterReactionSummary(chapterId) {
     var all = (state.data && state.data.reactions) || {};
     return normalizeReactionSummary(all[chapterId]);
   }

    function applyReactionResult(collection, targetId, result) {
      if (!result || !result.counts) return;
      if (!state.data[collection] || typeof state.data[collection] !== 'object' || Array.isArray(state.data[collection])) {
        state.data[collection] = {};
      }
      state.data[collection][targetId] = { counts: result.counts, userVote: result.userVote || null };
      render();
    }

    function chapterReactionLocal(chapterId, reaction) {
      if (!CONFIG.API_BASE_URL) { toast('Backend tidak terhubung.', 'error'); return; }
      apiPublicWrite('/api/chapter/reaction', { chapterId: chapterId, reaction: reaction })
        .then(function (res) { applyReactionResult('reactions', chapterId, res); })
        .catch(function (err) { toast('Gagal menyimpan reaksi: ' + (err && err.message ? err.message : err), 'error'); });
    }

    function mangaReactionSummary(mangaId) {
      var all = (state.data && state.data.mangaReactions) || {};
      return normalizeReactionSummary(all[mangaId]);
    }

    function mangaReactionLocal(mangaId, reaction) {
      if (!CONFIG.API_BASE_URL) { toast('Backend tidak terhubung.', 'error'); return; }
      apiPublicWrite('/api/manga/reaction', { mangaId: mangaId, reaction: reaction })
        .then(function (res) { applyReactionResult('mangaReactions', mangaId, res); })
        .catch(function (err) { toast('Gagal menyimpan reaksi: ' + (err && err.message ? err.message : err), 'error'); });
    }

    function adminPinComment(id) {
      if (!state.data.comments.some(function (x) { return x.id === id; })) return;
      apiSync('/api/admin/pin-comment', { id: id }, 'Status pin komentar diperbarui.');
    }

    function upvoteCommentLocal(id) {
      if (!CONFIG.API_BASE_URL) { toast('Backend tidak terhubung.', 'error'); return; }
      apiPublicWrite('/api/comment/upvote', { id: id }).then(function (res) {
        if (!res.comment || typeof res.comment.upvoteCount !== 'number') return;
        var c = state.data.comments.filter(function (x) { return x.id === id; })[0];
        if (!c) return;
        c.upvoteCount = res.comment.upvoteCount;
        c.userUpvoted = !!res.comment.userUpvoted;
        delete c.upvotes;
        render();
      }).catch(function (err) { toast('Gagal menyimpan upvote: ' + (err && err.message ? err.message : err), 'error'); });
    }

  function chapterById(id) {
    return state.data.chapters.filter(function (c) { return c.id === id; })[0] || null;
  }

  var readerAutoTimer = null;

  function stopAutoScroll() {
    if (readerAutoTimer) {
      clearInterval(readerAutoTimer);
      readerAutoTimer = null;
    }
    state.autoScroll = false;
  }

  function toggleAutoScroll() {
    if (readerAutoTimer) {
      stopAutoScroll();
      render();
      return;
    }
    state.autoScroll = true;
    readerAutoTimer = setInterval(function () {
      var doc = document.documentElement;
      var remaining = doc.scrollHeight - window.innerHeight - doc.scrollTop;
      if (remaining <= 16) {
        stopAutoScroll();
        render();
        return;
      }
       window.scrollBy(0, state.autoScrollSpeed || 2.5);

    }, 16);
    render();
  }

  /* Semua penulisan katalog wajib melalui backend; tidak ada mode lokal. */
  var apiSyncQueue = Promise.resolve();
  function parseApiResponse(res) {
    return res.json().catch(function () { return {}; }).then(function (json) {
      if (!res.ok) throw new Error(json.error || ('HTTP ' + res.status));
      return json;
    });
  }
  function apiPublicWrite(path, payload) {
    if (!CONFIG.API_BASE_URL) {
      toast('Backend tidak terhubung.', 'error');
      return Promise.reject(new Error('Backend tidak terhubung.'));
    }
    var headers = { 'Content-Type': 'application/json' };
    if (state.adminToken) headers.Authorization = 'Bearer ' + state.adminToken;
    return fetch(CONFIG.API_BASE_URL + path, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(payload || {})
    }).then(parseApiResponse);
  }
  function apiSync(path, payload, successMessage) {
    if (!CONFIG.API_BASE_URL || !state.adminToken) {
      toast('Backend tidak terhubung.', 'error');
      state.data = readCachedCatalog();
      render();
      return Promise.resolve(false);
    }
    apiSyncQueue = apiSyncQueue.then(function () {
      return fetch(CONFIG.API_BASE_URL + path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
        body: JSON.stringify(payload)
      }).then(function (res) {
        if (isSessionUnauthorized(res)) {
          clearSession();
          toast('Sesi admin berakhir. Silakan login ulang.', 'error');
          throw new Error('Sesi admin berakhir');
        }
        if (res.status === 401) throw new Error('Autentikasi tidak dapat diverifikasi.');
        return parseApiResponse(res);
      });
    }).then(function () {
      if (successMessage) toast(successMessage, 'ok');
      return syncFromApi();
    }).then(function () {
      return true;
    }).catch(function (err) {
      if (err && err.message === 'Sesi admin berakhir') {
        state.data = readCachedCatalog();
        render();
      } else {
        toast('Gagal menyimpan ke server (' + path + '): ' + (err && err.message ? err.message : err), 'error');
        state.data = readCachedCatalog();
        render();
        syncFromApi();
      }
      return false;
    });
    return apiSyncQueue;
  }

  /* Notifikasi toast (tidak ikut terhapus saat render ulang: diluar #kv-app) */
  function toast(msg, type) {
    var wrap = document.getElementById('kv-toasts');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.id = 'kv-toasts';
      wrap.className = 'kv-toasts';
      wrap.setAttribute('role', 'status');
      wrap.setAttribute('aria-live', 'polite');
      document.body.appendChild(wrap);
    }
    var kind = type === 'error' ? 'err' : type === 'success' ? 'ok' : (type || '');
    var t = document.createElement('div');
    t.className = 'kv-toast' + (kind ? ' kv-toast-' + kind : '');
    t.textContent = msg;
    wrap.appendChild(t);
    setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 4000);
  }

  function confirmDelete(type, id, label, confirmLabel) {
    state.pendingDelete = { type: type, id: id, label: label, confirmLabel: confirmLabel || 'Hapus' };
    render();
  }

