  function renderConfirmModal() {
    var d = state.pendingDelete;
    return '<div class="kv-modal" role="dialog" aria-modal="true" aria-label="Konfirmasi tindakan">' +
      '<div class="kv-modal-box">' +
        '<h2 class="kv-section-title" style="margin:0 0 10px;">' + escapeHtml(d.confirmLabel) + '</h2>' +
        '<p style="margin:0 0 6px;">' + escapeHtml(d.label) + '</p>' +
        '<p style="color:var(--kv-text-muted);font-size:0.8125rem;margin:0 0 18px;">Tindakan ini tidak dapat dibatalkan.</p>' +
        '<div style="display:flex;gap:10px;justify-content:flex-end;">' +
          '<button type="button" class="kv-btn kv-btn-ghost" data-action="cancel-delete">Batal</button>' +
          '<button type="button" class="kv-btn kv-btn-danger" data-action="confirm-delete">' + escapeHtml(d.confirmLabel) + '</button>' +
        '</div>' +
      '</div>' +
