  }

  function blankManga() {
    return { id: '', slug: '', title: '', altTitle: '', author: '', synopsis: '', coverBloggerUrl: '', genresText: '', type: 'Manga', status: 'Ongoing', rating: '', featured: false, recommended: false };
  }

  function blankChapter(mid) {
    var m = mid ? mangaById(mid) : state.data.manga[0];
    var mangaId = m ? m.id : '';
    var num = 1;
    state.data.chapters.filter(function (c) { return c.mangaId === mangaId; }).forEach(function (c) { if (c.number >= num) num = c.number + 1; });
    return { id: '', mangaId: mangaId, number: num, title: '', publishedAt: today(), pages: [] };
  }

  function saveMangaForm(form) {
    var err = document.getElementById('kv-manga-form-err');
    var fd = new FormData(form);
    var title = String(fd.get('title') || '').trim();
    var synopsis = String(fd.get('synopsis') || '').trim();
    var slug = slugify(fd.get('slug') || title);
    var rating = parseFloat(fd.get('rating'));
    var problems = [];
    if (title.length < 2) problems.push('Judul minimal 2 karakter.');
    if (synopsis.length < 10) problems.push('Sinopsis minimal 10 karakter.');
    if (!slug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) problems.push('Slug hanya boleh huruf kecil, angka, dan tanda hubung.');
    if (state.data.manga.filter(function (m) { return m.slug === slug && m.id !== (fd.get('id') || ''); }).length) problems.push('Slug sudah dipakai manga lain.');
    if (!isNaN(rating) && (rating < 0 || rating > 10)) problems.push('Rating harus antara 0 dan 10.');
    if (isNaN(rating)) rating = 0;
    if (problems.length) { if (err) err.textContent = problems.join(' '); return; }

    var genres = String(fd.get('genres') || '').split(',').map(function (g) { return g.trim(); }).filter(Boolean);
    var existing = mangaById(fd.get('id') || '');
    var obj = {
      id: existing ? existing.id : uid('mng'),
      slug: slug,
      title: title,
      altTitle: String(fd.get('altTitle') || '').trim(),
      author: String(fd.get('author') || '').trim(),
      synopsis: synopsis,
      coverBloggerUrl: String(fd.get('cover') || '').trim(),
      genres: genres,
      type: fd.get('type'),
      status: fd.get('status'),
      rating: rating,
      featured: fd.get('featured') === 'on',
      recommended: fd.get('recommended') === 'on',
      views: existing ? existing.views : 0,
      updatedAt: today()
    };
    apiSync('/api/admin/save-manga', obj, existing ? 'Perubahan manga disimpan.' : 'Manga baru dipublikasikan.').then(function (ok) {
      if (!ok) return;
      state.adminForm = null;
      render();
    });
  }

  function saveChapterForm(form) {
    var err = document.getElementById('kv-chapter-form-err');
    var fd = new FormData(form);
    var mangaId = fd.get('mangaId');
     var number = parseFloat(fd.get('number'));

    var title = String(fd.get('title') || '').trim();
    var publishedAt = fd.get('publishedAt') || today();
    var pages = state.adminChapterForm.pages || [];
    var problems = [];
    if (!mangaId) problems.push('Pilih manga terlebih dahulu.');
     if (isNaN(number) || number <= 0) problems.push('Nomor chapter harus angka > 0.');

    if (state.data.chapters.filter(function (c) { return c.mangaId === mangaId && c.number === number && c.id !== (fd.get('id') || ''); }).length) problems.push('Nomor chapter tersebut sudah dipakai di manga ini.');
    if (problems.length) { if (err) err.textContent = problems.join(' '); return; }

    var existing = chapterById(fd.get('id') || '');
    var obj = { id: existing ? existing.id : uid('ch'), mangaId: mangaId, number: number, title: title, publishedAt: publishedAt, pages: pages };
    apiSync('/api/admin/save-chapter', obj, existing ? 'Perubahan chapter disimpan.' : 'Chapter dipublikasikan.').then(function (ok) {
      if (!ok) return;
      state.adminChapterForm = null;
      state.adminChapterMangaId = mangaId;
      state.adminExpandedManga = mangaId;
      render();
    });
  }

  function moveChapter(mid, chId, dir) {
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === mid; }).sort(function (a, b) { return a.number - b.number; });
    var i = -1;
    chs.forEach(function (c, idx) { if (c.id === chId) i = idx; });
    var j = dir === 'up' ? i - 1 : i + 1;
    if (i === -1 || j < 0 || j >= chs.length) return;
    var first = Object.assign({}, chs[i], { number: chs[j].number });
    var second = Object.assign({}, chs[j], { number: chs[i].number });
    apiSync('/api/admin/save-chapter', first).then(function (ok) {
      if (!ok) return;
      return apiSync('/api/admin/save-chapter', second, 'Urutan chapter diperbarui.');
    });
  }

  function movePage(idx, dir) {
    var f = state.adminChapterForm;
    if (!f) return;
    var j = dir === 'up' ? idx - 1 : idx + 1;
    if (j < 0 || j >= f.pages.length) return;
    var tmp = f.pages[idx]; f.pages[idx] = f.pages[j]; f.pages[j] = tmp;
    reindexPages();
    render();
  }

  function removePage(idx) {
    var f = state.adminChapterForm;
    if (!f) return;
    f.pages.splice(idx, 1);
    reindexPages();
    render();
  }

  function reindexPages() {
    var f = state.adminChapterForm;
    if (!f) return;
    f.pages.forEach(function (p, i) { p.order = i + 1; });
  }

  function setCommentStatus(id, status) {
    if (!state.data.comments.some(function (x) { return x.id === id; })) { toast('Komentar tidak ditemukan.', 'warn'); return; }
    if (status !== 'approved' && status !== 'rejected' && status !== 'pending') return;
    var message = status === 'approved' ? 'Komentar disetujui & tampil publik.' : status === 'rejected' ? 'Komentar ditolak.' : 'Status komentar diperbarui.';
    apiSync('/api/admin/comment-status', { id: id, status: status }, message);
  }

  function performConfirmedDelete() {
    var d = state.pendingDelete;
    state.pendingDelete = null;
    if (!d) { render(); return; }
    if (d.type === 'manga') {
      state.adminExpandedManga = null;
      apiSync('/api/admin/delete-manga', { id: d.id }, 'Manga beserta chapter & komentarnya dihapus.');
      return;
    } else if (d.type === 'chapter') {
      apiSync('/api/admin/delete-chapter', { id: d.id }, 'Chapter dihapus.');
      return;
    } else if (d.type === 'comment') {
      apiSync('/api/admin/delete-comment', { id: d.id }, 'Komentar dihapus.');
      return;
    }
    render();
  }

  /* Unggah satu berkas per request; gambar disimpan di Telegram dan
     ditayangkan oleh URL proxy Vercel. */
   function compressImageBlob(blob, fileName) {
     return new Promise(function (resolve) {
       if (!blob || !blob.type || blob.type.indexOf('image/') !== 0) { resolve(blob); return; }
       if (state.imageCompressionEnabled === false) { resolve(blob); return; }
       if (blob.size <= 3 * 1024 * 1024) { resolve(blob); return; }
       var img = new Image();
       var url = URL.createObjectURL(blob);
       img.onload = function () {
         URL.revokeObjectURL(url);
         var maxDim = Math.max(500, Math.min(4000, Number(state.imageCompressionMaxDim) || 4000));
         var quality = Math.max(0.1, Math.min(1, Number(state.imageCompressionQuality) || 0.95));
         var w = img.naturalWidth || img.width;
         var h = img.naturalHeight || img.height;
         if (w > maxDim || h > maxDim) {
           var scale = Math.min(maxDim / w, maxDim / h);
           w = Math.round(w * scale);
           h = Math.round(h * scale);
         }
         var canvas = document.createElement('canvas');
         canvas.width = w;
         canvas.height = h;
         var ctx = canvas.getContext('2d');
         ctx.drawImage(img, 0, 0, w, h);
         canvas.toBlob(function (out) {
           if (!out) { resolve(blob); return; }
             if (out.type === 'image/webp') { resolve(out.size < blob.size ? out : blob); return; }
           canvas.toBlob(function (out2) {
             if (!out2 || out2.size >= blob.size) { resolve(blob); return; }
             resolve(out2);
           }, 'image/jpeg', quality);
         }, 'image/webp', quality);
       };
       img.onerror = function () { URL.revokeObjectURL(url); resolve(blob); };
       img.src = url;
     });
   }
   function compressImageFile(file) {
     if (!file || !file.type || file.type.indexOf('image/') !== 0) return Promise.resolve(file);
     return compressImageBlob(file, file.name).then(function (blob) {
       if (blob === file) return file;
       var ext = (blob.type === 'image/webp') ? '.webp' : (blob.type === 'image/jpeg' ? '.jpg' : '');
       var base = String(file.name || 'image').replace(/\.[^.]+$/, '');
       var name = ext ? (base + ext) : file.name;
       try { return new File([blob], name, { type: blob.type || file.type, lastModified: Date.now() }); }
       catch (e) { return file; }
     });
   }
   function mimeFromName(name) {

    var ext = String(name || '').split('.').pop().toLowerCase();
    return ({ jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif' })[ext] || 'image/jpeg';
  }
  function findEocd(bytes) {
    for (var i = bytes.length - 22; i >= 0; i--) {
      if (bytes[i] === 0x50 && bytes[i + 1] === 0x4b && bytes[i + 2] === 0x05 && bytes[i + 3] === 0x06) return i;
    }
    return -1;
  }
  async function extractZipImages(file) {
    var buf = await file.arrayBuffer();
    var bytes = new Uint8Array(buf);
    var eocd = findEocd(bytes);
    if (eocd < 0) throw new Error('ZIP tidak valid');
    var dv = new DataView(bytes.buffer);
    var numEntries = dv.getUint16(eocd + 10, true);
    var cdSize = dv.getUint32(eocd + 12, true);
    var cdOffset = dv.getUint32(eocd + 16, true);
    var pos = cdOffset;
    var entries = [];
    for (var i = 0; i < numEntries; i++) {
      if (dv.getUint32(pos, true) !== 0x02014b50) break;
      var method = dv.getUint16(pos + 10, true);
      var csize = dv.getUint32(pos + 20, true);
      var usize = dv.getUint32(pos + 24, true);
      var fnLen = dv.getUint16(pos + 28, true);
      var extraLen = dv.getUint16(pos + 30, true);
      var commentLen = dv.getUint16(pos + 32, true);
      var localOffset = dv.getUint32(pos + 42, true);
      var name = new TextDecoder().decode(bytes.slice(pos + 46, pos + 46 + fnLen));
      pos += 46 + fnLen + extraLen + commentLen;
      if (name.endsWith('/')) continue;
      var ext = name.split('.').pop().toLowerCase();
      if (['jpg', 'jpeg', 'png', 'webp', 'gif'].indexOf(ext) === -1) continue;
      entries.push({ name: name, method: method, csize: csize, usize: usize, localOffset: localOffset });
    }
    var out = [];
    for (var j = 0; j < entries.length; j++) {
      var e = entries[j];
      var lpos = e.localOffset;
      if (dv.getUint32(lpos, true) !== 0x04034b50) continue;
      var lfnLen = dv.getUint16(lpos + 26, true);
      var lextraLen = dv.getUint16(lpos + 28, true);
      var dataStart = lpos + 30 + lfnLen + lextraLen;
      var cdata = bytes.slice(dataStart, dataStart + e.csize);
      var blob = null;
      if (e.method === 0) {
        blob = new Blob([cdata], { type: mimeFromName(e.name) });
      } else if (e.method === 8) {
        try {
          var ds = new DecompressionStream('deflate-raw');
          var stream = new Blob([cdata]).stream().pipeThrough(ds);
          var ab = await new Response(stream).arrayBuffer();
          blob = new Blob([ab], { type: mimeFromName(e.name) });
        } catch (err) {
          continue;
        }
      } else {
        continue;
      }
      if (!blob) continue;
      out.push(new File([blob], e.name.split('/').pop(), { type: blob.type }));
    }
    return out;
  }
  function uploadOneFile(file, f) {
    return new Promise(function (resolve) {
      var page = { order: f.pages.length + 1, fileName: file.name, bloggerUrl: '', telegramFileId: '', status: 'menunggu unggah' };
      f.pages.push(page);
      if (file.size > 3 * 1024 * 1024) {
        page.status = 'gagal: ukuran maksimal 3 MiB';
        toast('Ukuran ' + file.name + ' melebihi batas 3 MiB untuk backend Vercel.', 'err');
        render();
        resolve();
        return;
      }
      render();
      if (!CONFIG.API_BASE_URL) {
        page.status = 'gagal: backend belum dikonfigurasi';
        toast('Backend belum dikonfigurasi untuk upload halaman.', 'warn');
        render();
        resolve();
        return;
      }
      page.status = 'mengunggah ke proxy...';
      render();
      var fr = new FileReader();
      fr.onload = function () {
        fetch(CONFIG.API_BASE_URL + '/api/admin/upload-dual', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
          body: JSON.stringify({ fileName: file.name, mimeType: file.type || mimeFromName(file.name), dataBase64: fr.result })
        }).then(function (r) {
          return r.json().then(function (res) {
            if (!r.ok) throw new Error(res.error || 'HTTP ' + r.status);
            return res;
          });
        }).then(function (res) {
          page.telegramFileId = (res && res.telegramFileId) || '';
          page.bloggerUrl = (res && res.bloggerUrl) || '';
          page.status = 'Telegram: ' + ((res && res.telegramStatus) || 'gagal') + ' | Proxy: ' + ((res && res.bloggerStatus) || 'gagal');
          if (!page.bloggerUrl || !page.telegramFileId) {
            toast('Sebagian tujuan gagal untuk ' + file.name + ' - periksa status lalu unggah ulang.', 'warn');
          }
          render();
          resolve();
        }).catch(function (err) {
          page.status = 'gagal: ' + err.message;
          toast('Gagal mengunggah ' + file.name + ': ' + err.message, 'err');
          render();
          resolve();
        });
      };
      fr.readAsDataURL(file);
    });
  }
  async function uploadPageFiles(files) {
    var f = state.adminChapterForm;
    if (!f) return;
    var collected = [];
    for (var i = 0; i < files.length; i++) {
      var file = files[i];
      var name = String(file.name || '').toLowerCase();
      if (name.endsWith('.zip') || file.type === 'application/zip' || file.type === 'application/x-zip-compressed') {
        try {
          var extracted = await extractZipImages(file);
          if (!extracted.length) toast('ZIP tidak berisi gambar yang didukung.', 'warn');
          collected = collected.concat(extracted);
        } catch (err) {
          toast('Gagal mengekstrak ZIP ' + file.name + ': ' + err.message, 'err');
        }
      } else {
        var compressed = await compressImageFile(file);
        collected.push(compressed);
      }
    }
    if (!collected.length) {
      toast('Tidak ada gambar untuk diunggah.', 'warn');
      render();
      return;
    }
    state.uploadProgress = { active: true, total: collected.length, done: 0, current: collected[0].name };
    render();
    for (var j = 0; j < collected.length; j++) {
      state.uploadProgress.current = collected[j].name;
      state.uploadProgress.done = j;
      render();
      await uploadOneFile(collected[j], f);
      state.uploadProgress.done = j + 1;
      render();
    }
    state.uploadProgress.active = false;
    state.uploadProgress = null;
    render();
    toast('Unggah selesai: ' + collected.length + ' gambar.', 'ok');
  }

  function renderInfo() {
    var p = state.params.page;
    var about = siteSetting('aboutContent', siteLabel() + ' dibangun dengan antarmuka Blogger yang ringan, archive dan media tersimpan di Telegram melalui backend Vercel.');
    var contact = siteSetting('contactContent', siteContact() ? 'Hubungi kami melalui: ' + siteContact() : 'Belum ada kontak yang diatur.');
    var privacy = siteSetting('privacyContent', 'Kami menghargai privasi kamu. Data akun digunakan sesuai kebutuhan layanan membaca, komentar, dan sinkronisasi preferensi. Kami tidak menjual data pribadi ke pihak ketiga.');
    var terms = siteSetting('termsContent', 'Gunakan katalog ini dengan bijak. Dilarang menyebarkan konten bajakan, spam, atau komentar yang melanggar hukum. Hak cipta manga tetap milik pemilik haknya.');
    var pages = {
      tentang: { title: 'Tentang ' + siteLabel(), content: about },
      kontak: { title: 'Kontak Redaksi', content: contact },
      privasi: { title: 'Kebijakan Privasi', content: privacy },
      ketentuan: { title: 'Ketentuan Penggunaan', content: terms }
    };
    var page = pages[p] || pages.tentang;
    return '<main class="kv-container" style="max-width:760px;margin-top:32px;">' +
      '<h1 style="font-size:1.75rem;font-weight:800;">' + escapeHtml(page.title) + '</h1>' +
      '<div class="kv-stat-box kv-info-content" style="margin-top:16px;">' +
        escapeHtml(page.content) +
      '</div>' +
    '</main>';
  }

  function render404() {
    return '<main class="kv-container" style="text-align:center;margin-top:64px;">' +
      '<div class="kv-mono kv-404" style="font-size:3rem;font-weight:800;color:var(--kv-accent);">404</div>' +
      '<h1>Halaman Tidak Ditemukan</h1>' +
      '<p style="color:var(--kv-text-muted);">Tautan manga atau chapter yang Anda tuju tidak tersedia.</p>' +
      '<a class="kv-btn kv-btn-primary" href="#/">Kembali ke Beranda</a>' +
    '</main>';
  }

  /* =========================================================================
     RENDER UTAMA & EVENT HANDLERS
     ========================================================================= */
   function render() {

     var app = document.getElementById('kv-app');
     if (!app) return;
      hideTrafficTooltip();
      applyFavicon();
      applyEmbed();
      if (document.body) {
        document.body.classList.toggle('kv-home-route', state.route === 'home' || state.route === 'catalog' || state.route === 'account' || state.route === 'notification' || state.route === 'info');
        document.body.classList.toggle('kv-detail-route', state.route === 'detail');
         document.body.classList.toggle('kv-account-route', state.route === 'account');
         document.body.classList.toggle('kv-notification-route', state.route === 'notification');
        document.body.classList.toggle('kv-reader-route', state.route === 'reader');
        document.body.classList.toggle('kv-public-route', state.route !== 'reader' && state.route !== 'admin');
      }


    var bodyHtml = '';
    if (state.loading) {
      bodyHtml = '<div class="kv-container" style="margin-top:40px;"><div class="kv-stat-box">Memuat...</div></div>';
    } else if (state.error) {
      bodyHtml = '<div class="kv-container" style="margin-top:40px;"><div class="kv-stat-box"><strong>Terjadi Kesalahan:</strong> ' + escapeHtml(state.error) + '<div style="margin-top:12px;"><button type="button" class="kv-btn kv-btn-ghost" data-action="retry-api">Coba Lagi</button></div></div></div>';
    } else {
      if (state.route === 'home') bodyHtml = renderHome();
      else if (state.route === 'catalog') bodyHtml = renderCatalog();
      else if (state.route === 'detail') bodyHtml = renderDetail();
      else if (state.route === 'reader') bodyHtml = renderReader();
      else if (state.route === 'account') bodyHtml = renderAccount();
      else if (state.route === 'notification') bodyHtml = renderNotifications();
      else if (state.route === 'admin') bodyHtml = renderAdmin();
      else if (state.route === 'info') bodyHtml = renderInfo();
      else bodyHtml = render404();
    }
    if (state.route === 'admin' && state.mdProgress && state.mdProgress.active) {
      var mp = state.mdProgress;
      var mppct = mp.total ? Math.round((mp.done / mp.total) * 100) : 0;
      if (!mp.dismissed) {
        bodyHtml += '<div class="kv-upload-overlay" role="dialog" aria-modal="true" aria-label="Scrape MangaDex">' +
          '<div class="kv-upload-box">' +
            '<button type="button" class="kv-upload-close" data-action="md-progress-close" aria-label="Tutup">&times;</button>' +
            '<div class="kv-upload-title">Scraping MangaDex</div>' +
            '<div class="kv-upload-sub">' + escapeHtml(mp.current || '') + '</div>' +
            '<div class="kv-upload-bar"><div class="kv-upload-bar-fill" style="width:' + mppct + '%;"></div></div>' +
            '<div class="kv-upload-count">' + mp.done + ' / ' + mp.total + ' chapter (' + mppct + '%)</div>' +
          '</div>' +
        '</div>';
      } else {
        bodyHtml += '<div class="kv-scrape-indicator" role="status" aria-live="polite">' +
          '<div class="kv-scrape-indicator-bar"><div class="kv-scrape-indicator-fill" style="width:' + mppct + '%;"></div></div>' +
          '<span class="kv-scrape-indicator-text">Scrape ' + mp.done + '/' + mp.total + '</span>' +
          '<button type="button" class="kv-scrape-indicator-btn" data-action="md-progress-open" aria-label="Buka progres">…</button>' +
        '</div>';
      }
    }
    if (state.route === 'admin' && state.uploadProgress && state.uploadProgress.active) {
      var up = state.uploadProgress;
      var pct = up.total ? Math.round((up.done / up.total) * 100) : 0;
      bodyHtml += '<div class="kv-upload-overlay" role="dialog" aria-modal="true" aria-label="Proses unggah">' +
        '<div class="kv-upload-box">' +
          '<div class="kv-upload-title">Mengunggah Gambar</div>' +
          '<div class="kv-upload-sub">' + escapeHtml(up.current || '') + '</div>' +
          '<div class="kv-upload-bar"><div class="kv-upload-bar-fill" style="width:' + pct + '%;"></div></div>' +
          '<div class="kv-upload-count">' + up.done + ' / ' + up.total + ' selesai (' + pct + '%)</div>' +
        '</div>' +
      '</div>';
    }
    if (state.route === 'admin' && state.pendingDelete) bodyHtml += renderConfirmModal();
    var runtimeNotice = state.sessionNotice || state.catalogNotice;
    var renderScrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    app.innerHTML = renderHeader() + (runtimeNotice ? '<div class="kv-runtime-notice" role="status">' + escapeHtml(runtimeNotice) + '</div>' : '') + bodyHtml + renderFooter() + renderPublicBottomNav();
    window.scrollTo(0, renderScrollY);
    bindEvents();
  }

  function setBannerDotsActive(index) {
    var dots = document.querySelectorAll('#kv-banner-dots .kv-home-banner-dot');
    for (var i = 0; i < dots.length; i++) {
      var active = i === index;
      dots[i].classList.toggle('is-active', active);
      dots[i].setAttribute('aria-selected', active ? 'true' : 'false');
    }
  }

  function bindBannerTrack(track) {
    if (track.dataset.keysBound === '1') return;
    track.dataset.keysBound = '1';
    var syncDots = function () {
      var center = track.scrollLeft + track.clientWidth / 2;
      var bestIndex = 0;
      var bestDistance = Infinity;
      for (var i = 0; i < track.children.length; i++) {
        var child = track.children[i];
        var childCenter = child.offsetLeft + child.offsetWidth / 2;
        var distance = Math.abs(childCenter - center);
        if (distance < bestDistance) {
          bestDistance = distance;
          bestIndex = i;
        }
      }
      setBannerDotsActive(bestIndex);
    };
    var loopTicking = false;
    var loopCooldownUntil = 0;
    var ticking = false;
    track.addEventListener('scroll', function () {
      if (ticking) return;
      ticking = true;
      window.requestAnimationFrame(function () {
        syncDots();
        ticking = false;
      });
    }, { passive: true });
    track.addEventListener('scroll', function () {
      if (loopTicking) return;
      loopTicking = true;
      window.requestAnimationFrame(function () {
        loopTicking = false;
        if (Date.now() < loopCooldownUntil) return;
        var max = track.scrollWidth - track.clientWidth;
        if (max <= 0) return;
        var sl = track.scrollLeft;
        if (sl >= max - 1) {
          track.scrollTo({ left: 0, behavior: 'smooth' });
          loopCooldownUntil = Date.now() + 350;
        }
      });
    }, { passive: true });
    track.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowLeft') { e.preventDefault(); track.scrollBy({ left: -Math.max(320, Math.round(track.clientWidth * 0.72)), behavior: 'smooth' }); }
      else if (e.key === 'ArrowRight') { e.preventDefault(); track.scrollBy({ left: Math.max(320, Math.round(track.clientWidth * 0.72)), behavior: 'smooth' }); }
    });
    syncDots();
  }

  function updateControlsToggle() {
    var btn = document.querySelector('.kv-reader-controls-toggle');
    if (!btn) return;
    var hidden = state.readerControlsHidden;
    btn.setAttribute('aria-label', hidden ? 'Tampilkan tombol pembaca' : 'Sembunyikan tombol pembaca');
    btn.setAttribute('aria-pressed', hidden ? 'true' : 'false');
    btn.classList.toggle('is-hidden-controls', hidden);
    btn.innerHTML = hidden
      ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 6.3A10.7 10.7 0 0 1 12 6.2c6.1 0 9.6 5.8 9.6 5.8a15.3 15.3 0 0 1-3.2 3.7M6.3 8.4A15.1 15.1 0 0 0 2.4 12s3.5 5.8 9.6 5.8a10.4 10.4 0 0 0 3.5-.6"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>'
      : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.4 12s3.5-5.8 9.6-5.8 9.6 5.8 9.6 5.8-3.5 5.8-9.6 5.8S2.4 12 2.4 12z"/><circle cx="12" cy="12" r="2.7"/></svg>';
  }

  function toggleOverlayVisibility() {
    var overlay = document.getElementById('kv-reader-overlay');
    if (!overlay) return;
    state.readerControlsHidden = !state.readerControlsHidden;
    overlay.classList.toggle('kv-reader-overlay-hidden', state.readerControlsHidden);
    updateControlsToggle();
  }

  function updateOverlayDockState() {
    var overlay = document.getElementById('kv-reader-overlay');
    var frame = document.querySelector('.kv-reader-frame');
    if (!overlay || !frame) return;
    var settled = frame.getBoundingClientRect().bottom <= window.innerHeight;
    overlay.classList.toggle('kv-reader-overlay-settled', settled);
    updateControlsToggle();
  }

  function bindEvents() {
    if (!window.__kvDockBound) {
      window.__kvDockBound = true;
      window.addEventListener('scroll', updateOverlayDockState, { passive: true });
      window.addEventListener('resize', updateOverlayDockState);
    }
    var readerFrame = document.querySelector('.kv-reader-frame');
    if (readerFrame) {
      readerFrame.addEventListener('click', function (event) {
        var target = event.target;
        if (target && target.closest && target.closest('button, a, select, input, textarea, [role="dialog"], .kv-reader-overlay, .kv-reader-sheet')) return;
        toggleOverlayVisibility();
      });
    }
    if (state.readerDockTimer) clearInterval(state.readerDockTimer);
    state.readerDockTimer = setInterval(updateOverlayDockState, 400);
    updateOverlayDockState();
    document.body.style.overflow = (state.readerMenuOpen || state.readerSettingsOpen) ? 'hidden' : '';
    var sInput = document.getElementById('kv-search-input');
    if (sInput) sInput.oninput = function (e) { state.search = e.target.value; state.page = 1; state.refocusSearch = true; if (state.route !== 'catalog') { state.route = 'catalog'; state.params = {}; try { window.history.replaceState(null, '', '#/archive'); } catch (err) {} parseRoute(); render(); } else { render(); } };
    // Pertahankan fokus kursor di kolom pencarian setelah render ulang
    if (sInput && state.refocusSearch) {
      state.refocusSearch = false;
      sInput.focus();
      var len = sInput.value.length;
      sInput.setSelectionRange(len, len);
    }
    var catalogToolbar = document.querySelector('[data-catalog-toolbar]');
    if (catalogToolbar) {
      var genreChecks = catalogToolbar.querySelectorAll('.kv-filter-check');
      genreChecks.forEach(function (checkbox) {
        checkbox.onchange = function () {
          var genre = checkbox.getAttribute('data-genre') || '';
          if (!Array.isArray(state.filterGenres)) state.filterGenres = [];
          if (checkbox.checked) {
            if (state.filterGenres.indexOf(genre) === -1) state.filterGenres.push(genre);
          } else {
            state.filterGenres = state.filterGenres.filter(function (item) { return item !== genre; });
          }
          state.openCatalogDropdown = 'genre';
          state.page = 1;
          render();
        };
      });
    }
    var pPrev = document.getElementById('kv-page-prev');
    if (pPrev) pPrev.onclick = function () { if (state.page > 1) { state.page--; render(); window.scrollTo(0, 0); } };
    var pNext = document.getElementById('kv-page-next');
    if (pNext) pNext.onclick = function () { state.page++; render(); window.scrollTo(0, 0); };

     var chSearch = document.getElementById('chapter-search');
     if (chSearch) chSearch.oninput = function (e) { state.chapterSearch = e.target.value; state.chapterRefocus = true; render(); };
     if (chSearch && state.chapterRefocus) {
       state.chapterRefocus = false;
       chSearch.focus();
       var chLen = chSearch.value.length;
       chSearch.setSelectionRange(chLen, chLen);
     }
    var bTrack = document.getElementById('kv-banner-track');
    if (bTrack) {
      if (bTrack.dataset.centered !== '1') {
        var middleChild = bTrack.children[Math.floor(bTrack.children.length / 2)] || bTrack.children[0];
        if (middleChild && typeof middleChild.scrollIntoView === 'function') {
          middleChild.scrollIntoView({ inline: 'center', block: 'nearest' });
        } else {
          bTrack.scrollLeft = Math.max(0, (bTrack.scrollWidth - bTrack.clientWidth) / 2);
        }
        bTrack.dataset.centered = '1';
      }
      bindBannerTrack(bTrack);
    }
     var rWidth = document.getElementById('kv-reader-width');
     if (rWidth) rWidth.onchange = function (e) { state.readerWidth = Number(e.target.value); render(); };
      var rSpeed = document.getElementById('kv-reader-speed');
      if (rSpeed) rSpeed.onchange = function (e) { var v = parseFloat(e.target.value); if (isNaN(v) || v <= 0) v = 2.5; state.autoScrollSpeed = v; render(); };
      var rChSearch = document.getElementById('kv-reader-chapter-search');
      if (rChSearch) rChSearch.oninput = function (e) { state.readerChapterSearch = e.target.value; state.readerChapterSearchRefocus = true; render(); };
      if (rChSearch && state.readerChapterSearchRefocus) {
        state.readerChapterSearchRefocus = false;
        rChSearch.focus();
        var rcl = rChSearch.value.length;
        rChSearch.setSelectionRange(rcl, rcl);
      }

    var rDir = document.getElementById('kv-reader-dir');
    if (rDir) rDir.onchange = function (e) { state.readerDir = e.target.value; render(); };

    var pForm = document.getElementById('kv-profile-form');
    if (pForm) {
      pForm.onsubmit = function (e) {
        e.preventDefault();
        var fd = new FormData(pForm);
        var name = String(fd.get('name') || '').trim();
        var avatar = String(fd.get('avatar') || '').trim();
        var background = String(fd.get('background') || '').trim();
        var bgFile = fd.get('backgroundFile');
        if (name.length < 2) { toast('Nama minimal 2 karakter.', 'warn'); return; }
        var overrideId = state.user && state.user.id;
        if (!overrideId) { toast('Masuk terlebih dahulu untuk menyimpan profil.', 'warn'); return; }
        var save = function (bgValue) {
          try { localStorage.setItem('kv_profile_override_v2_' + overrideId, JSON.stringify({ name: name, avatar: avatar, background: bgValue || background || '' })); } catch (err) { toast('Gagal menyimpan profil di browser.', 'warn'); }
          state.editingProfile = false;
          toast('Profil berhasil disimpan.', 'ok');
          render();
        };
        if (bgFile && bgFile.size) {
          var token = state.adminToken || localStorage.getItem('kv_session_token') || '';
          if (CONFIG.API_BASE_URL && token) {
            state.adminToken = token;
            var reader = new FileReader();
            reader.onload = function (ev) {
              var dataUrl = String(ev.target.result || '');
              toast('Mengunggah background ke Telegram...', 'info');
              fetch(CONFIG.API_BASE_URL + '/api/profile/upload-background', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                body: JSON.stringify({ fileName: bgFile.name || 'background.jpg', dataBase64: dataUrl })
              }).then(function (res) { return res.json().then(function (json) { return { ok: res.ok, status: res.status, json: json }; }); })
                .then(function (result) {
                  if (!result.ok) throw new Error((result.json && result.json.error) || ('HTTP ' + result.status));
                  save((result.json && (result.json.url || result.json.bloggerUrl)) || dataUrl);
                  toast('Background tersimpan di Telegram.', 'ok');
                })
                .catch(function (err) {
                  toast('Gagal unggah ke Telegram: ' + (err && err.message ? err.message : 'unknown'), 'err');
                });
            };
            reader.onerror = function () { toast('Gagal membaca file.', 'err'); };
            reader.readAsDataURL(bgFile);
          } else {
            toast('Backend/token tidak tersedia. Upload background ke Telegram tidak bisa dilakukan.', 'err');
          }
        } else {
          save(background);
        }
      };
    }

    var sForm = document.getElementById('kv-site-settings-form');
    if (sForm) {
      sForm.onsubmit = function (e) {
        e.preventDefault();
        var fd = new FormData(sForm);
        persistSiteSettings({
          siteName: String(fd.get('siteName') || '').trim(),
          siteTagline: String(fd.get('siteTagline') || '').trim(),
          logoUrl: String(fd.get('logoUrl') || '').trim(),
          faviconUrl: String(fd.get('faviconUrl') || '').trim(),
          contactEmail: String(fd.get('contactEmail') || '').trim(),
          brandMode: String(fd.get('brandMode') || 'logo-name').trim(),
          siteNameColor: normalizeHexColor(sForm.querySelector('.kv-color-hex') ? sForm.querySelector('.kv-color-hex').value : fd.get('siteNameColor'))
        });
      };
      var colorStudio = sForm.querySelector('[data-color-studio]');
      if (colorStudio) bindColorStudio(sForm, colorStudio);
    }

    var infoForm = document.getElementById('kv-info-settings-form');
    if (infoForm) {
      infoForm.onsubmit = function (e) {
        e.preventDefault();
        var fd = new FormData(infoForm);
        persistSiteSettings({
          aboutContent: String(fd.get('aboutContent') || '').trim(),
          contactContent: String(fd.get('contactContent') || '').trim(),
          privacyContent: String(fd.get('privacyContent') || '').trim(),
          termsContent: String(fd.get('termsContent') || '').trim()
         });
       };
     }

     var compressForm = document.getElementById('kv-compress-settings-form');
     if (compressForm) {
       compressForm.onsubmit = function (e) {
         e.preventDefault();
         var fd = new FormData(compressForm);
         var enabled = fd.get('enabled') === 'on';
         var q = parseFloat(fd.get('quality'));
         if (isNaN(q) || q < 0.1 || q > 1) q = 0.95;
         var md = parseInt(fd.get('maxDim'), 10);
         if (isNaN(md) || md < 500 || md > 4000) md = 4000;
         state.imageCompressionEnabled = enabled;
         state.imageCompressionQuality = q;
         state.imageCompressionMaxDim = md;
         localStorage.setItem('kv_img_compress_enabled', enabled ? '1' : '0');
         localStorage.setItem('kv_img_compress_quality', String(q));
         localStorage.setItem('kv_img_compress_maxdim', String(md));
         toast('Pengaturan kompresi disimpan.', 'ok');
         render();
       };
     }

    function uploadSiteAsset(file, inputId, previewSelector, label) {
      if (!CONFIG.API_BASE_URL || !state.adminToken) { toast('Upload ' + label.toLowerCase() + ' hanya tersedia saat terhubung ke backend.', 'warn'); return; }
      var reader = new FileReader();
      reader.onload = function () {
        fetch(CONFIG.API_BASE_URL + '/api/admin/upload-dual', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
          body: JSON.stringify({ fileName: file.name, mimeType: file.type, dataBase64: reader.result })
        }).then(function (r) {
          return r.json().catch(function () { return {}; }).then(function (res) {
            if (isSessionUnauthorized(r)) {
              clearSession();
              throw new Error('Sesi admin berakhir. Silakan login ulang.');
            }
            if (r.status === 401) throw new Error('HTTP 401');
            if (!r.ok) throw new Error(res.error || ('HTTP ' + r.status));
            return res;
          });
        }).then(function (res) {
          var url = res.bloggerUrl || '';
          var input = document.getElementById(inputId);
          if (input) input.value = url;
          var preview = sForm && sForm.querySelector(previewSelector);
          if (preview) preview.innerHTML = '<img src="' + escapeHtml(url) + '" alt="Preview ' + label + '"/>';
          toast(label + ' berhasil diunggah. Klik Simpan Pengaturan untuk menerapkan.', 'ok');
        }).catch(function (err) { toast('Gagal mengunggah ' + label.toLowerCase() + ': ' + err.message, 'error'); });
      };
      compressImageFile(file).then(function (cf) { reader.readAsDataURL(cf); }).catch(function () { reader.readAsDataURL(file); });
    }

    var logoBtn = document.getElementById('kv-logo-upload-btn');
    var logoFile = document.getElementById('kv-logo-file');
    if (logoBtn && logoFile) {
      logoBtn.onclick = function () {
        if (!CONFIG.API_BASE_URL || !state.adminToken) { toast('Upload logo hanya tersedia saat terhubung ke backend.', 'warn'); return; }
        logoFile.click();
      };
      logoFile.onchange = function (e) {
        var file = e.target.files && e.target.files[0];
        if (file) uploadSiteAsset(file, 'kv-setting-logoUrl', '.kv-site-logo-preview', 'Logo');
      };
    }

    var faviconBtn = document.getElementById('kv-favicon-upload-btn');
    var faviconFile = document.getElementById('kv-favicon-file');
    if (faviconBtn && faviconFile) {
      faviconBtn.onclick = function () {
        if (!CONFIG.API_BASE_URL || !state.adminToken) { toast('Upload favicon hanya tersedia saat terhubung ke backend.', 'warn'); return; }
        faviconFile.click();
      };
      faviconFile.onchange = function (e) {
        var file = e.target.files && e.target.files[0];
        if (file) uploadSiteAsset(file, 'kv-setting-faviconUrl', '.kv-site-favicon-preview', 'Favicon');
      };
    }


    var cForm = document.getElementById('kv-comment-form');
    if (cForm) {
       cForm.onsubmit = function (e) {
         e.preventDefault();
         var fd = new FormData(cForm);
          var mangaId = cForm.getAttribute('data-manga-id');
          var chapterId = cForm.getAttribute('data-chapter-id') || null;
          var parentId = cForm.getAttribute('data-parent-id') || null;
          var authorName = state.user ? state.user.name : 'Pengunjung';
          var authorAvatar = state.user ? (state.user.avatar || null) : null;
           var content = replaceImageTokens(String(fd.get('content') || ''));
           apiPublicWrite('/api/comment', {
             mangaId: mangaId,
             chapterId: chapterId,
             parentId: parentId,
             replyTo: null,
             authorName: authorName,
             authorAvatar: authorAvatar,
             content: content
           }).then(function () {
             state.commentNotice = 'Komentar Anda berhasil dikirim dan menunggu moderasi. Terima kasih!';
             state.replyingTo = null;
             render();
             syncFromApi();
           }).catch(function (err) {
             toast('Gagal mengirim komentar: ' + (err && err.message ? err.message : err), 'error');
           });
        };
     }

     document.querySelectorAll('.kv-reply-form').forEach(function (rf) {
       rf.onsubmit = function (e) {
         e.preventDefault();
         var fd = new FormData(rf);
         var mangaId = rf.getAttribute('data-manga-id');
         var chapterId = rf.getAttribute('data-chapter-id') || null;
         var parentId = rf.getAttribute('data-parent-id');
          var authorName = state.user ? state.user.name : 'Pengunjung';
          var authorAvatar = state.user ? (state.user.avatar || null) : null;
           var replyTo = rf.getAttribute('data-reply-to') || null;
           var content = replaceImageTokens(String(fd.get('content') || ''));
           apiPublicWrite('/api/comment', {
             mangaId: mangaId,
             chapterId: chapterId,
             parentId: parentId,
             replyTo: replyTo,
             authorName: authorName,
             authorAvatar: authorAvatar,
             content: content
           }).then(function () {
             state.commentNotice = 'Balasan Anda berhasil dikirim dan menunggu moderasi.';
             state.replyingTo = null;
             render();
             syncFromApi();
           }).catch(function (err) {
             toast('Gagal mengirim balasan: ' + (err && err.message ? err.message : err), 'error');
           });
        };
      });

     var imgFile = document.getElementById('kv-comment-image-file');
     if (imgFile) {
       imgFile.onchange = function (e) {
         var file = e.target.files && e.target.files[0];
         var targetForm = state.imageTargetForm;
         state.imageTargetForm = null;
          if (!file || !targetForm) return;
          if (!CONFIG.API_BASE_URL) { toast('Upload gambar butuh backend yang terhubung.', 'warn'); return; }
           var btn = state.commentImageUploadingBtn;
           if (btn) { btn.disabled = true; btn.innerHTML = '<span class="kv-spinner"></span>'; }
           var reader = new FileReader();
           var uploadFile = file;


         reader.onload = function () {
           var headers = { 'Content-Type': 'application/json' };
           if (state.adminToken) headers['Authorization'] = 'Bearer ' + state.adminToken;
           fetch(CONFIG.API_BASE_URL + '/api/comment/image', {
             method: 'POST',
             headers: headers,
              body: JSON.stringify({ fileName: uploadFile.name, mimeType: uploadFile.type, dataBase64: reader.result })

           }).then(function (r) {
             return r.json().then(function (res) {
               if (!r.ok) throw new Error(res.error || ('HTTP ' + r.status));
               return res;
             });
            }).then(function (res) {
              var textarea = targetForm.querySelector('textarea');
              state.commentImageIndex = (state.commentImageIndex || 0) + 1;
              var token = '[gambar' + state.commentImageIndex + ']';
              if (textarea) {
                var start = textarea.selectionStart || 0;
