  // Shortcut reader: j/k untuk gulir, panah untuk ganti halaman, f untuk layar penuh
  document.addEventListener('keydown', function (e) {
    if (state.route !== 'reader') return;
    var t = e.target;
    if (t && (['INPUT', 'TEXTAREA', 'SELECT'].indexOf(t.tagName) !== -1)) return;
    var key = e.key.toLowerCase();
    if (key === 'j' || e.key === 'ArrowDown') { window.scrollBy({ top: 400, behavior: 'smooth' }); }
    else if (key === 'k' || e.key === 'ArrowUp') { window.scrollBy({ top: -400, behavior: 'smooth' }); }
    else if ((key === 'arrowleft' || key === 'arrowright' || e.key === ' ') && state.readerMode === 'paged') {
      var ch = chapterById(state.params && state.params.chapterId);
      var max = ch ? Math.max(0, (ch.pages || []).length - 1) : 0;
      if (key === 'arrowleft') state.currentPageIdx = Math.max(0, state.currentPageIdx - 1);
      else { state.currentPageIdx = Math.min(max, state.currentPageIdx + 1); if (e.key === ' ') e.preventDefault(); }
      render();
      window.scrollTo(0, 0);
    }
    else if (key === 'f') {
      if (document.fullscreenElement) { document.exitFullscreen().catch(function () {}); }
      else if (document.documentElement.requestFullscreen) { document.documentElement.requestFullscreen().catch(function () {}); }
    }
    else if (key === 'p') { toggleAutoScroll(); }
  });

  // Aksesibilitas: elemen interaktif custom (kartu/baris) dapat diaktifkan via Enter/Spasi
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      var brandPanel = document.getElementById('kv-brand-mode-panel');
      if (brandPanel && !brandPanel.hidden) { setBrandModePanel(false); return; }
      if (state.mdLangMenuOpen) { setMdLangMenu(false); var mdLangBtnEsc = document.getElementById('kv-md-lang-btn'); if (mdLangBtnEsc) mdLangBtnEsc.focus(); return; }
      var trafficTip = document.getElementById('kv-traffic-tooltip');
      if (trafficTip && !trafficTip.hidden) { hideTrafficTooltip(); return; }
    }
    if (e.key === 'Escape' && state.openCatalogDropdown) {
      state.openCatalogDropdown = null;
      render();
      return;
    }
    if (e.key === 'Escape' && state.adminRoleMenuOpen) {
      state.adminRoleMenuOpen = null;
      render();
      return;
    }
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var t = e.target;
    if (!t || !t.getAttribute) return;
    if (['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].indexOf(t.tagName) !== -1) return;
    if (!t.hasAttribute('data-action')) return;
    e.preventDefault();
    t.click();
  });


  function handleRouteChange() {
    stopAutoScroll();
    if (state.readerDockTimer) {
      clearInterval(state.readerDockTimer);
      state.readerDockTimer = null;
    }
    state.readerMenuOpen = false;
    state.readerSettingsOpen = false;
    state.readerControlsHidden = false;
    state.commentNotice = null;
    parseRoute();
    render();
    window.scrollTo(0, 0);
  }

  // Toggle spoiler komentar saat diklik
  document.addEventListener('click', function (e) {
    var sp = e.target && e.target.closest ? e.target.closest('.kv-spoiler-toggle') : null;
    if (!sp) return;
    var box = sp.closest('.kv-spoiler');
    if (box) box.classList.toggle('open');
  });

  window.addEventListener('popstate', handleRouteChange);
  window.addEventListener('hashchange', handleRouteChange);


  window.addEventListener('storage', function (e) {
    if (e.key === 'kv_session_token') {
      var nextToken = e.newValue;
      if (nextToken && nextToken !== state.adminToken) {
        state.adminToken = nextToken;
        state.user = restoreSessionFromCache(decodeSessionClaims(nextToken));
        refreshSession(true);
        render();
      } else if (!nextToken && state.adminToken) {
        clearSession();
        render();
        syncFromApi(true);
      }
      return;
    }
    if (e.key === 'kv_theme') {
      var t = e.newValue;
      if (CONFIG.THEME_IDS.indexOf(t) === -1) t = CONFIG.DEFAULT_THEME;
      if (state.theme !== t) { state.theme = t;  applyTheme(false); render(); }
    }
  });
  var themeMedia = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
  if (themeMedia) {
    var onThemePreferenceChange = function () { if (state.theme === 'system') { applyTheme(false); render(); } };
    if (themeMedia.addEventListener) themeMedia.addEventListener('change', onThemePreferenceChange);
    else if (themeMedia.addListener) themeMedia.addListener(onThemePreferenceChange);
  }
  window.addEventListener('online', function () {
    refreshSession(true);
    syncFromApi(true);
  });
  document.addEventListener('visibilitychange', function () {
    if (!document.hidden && navigator.onLine) {
      refreshSession(true);
      syncFromApi(true);
    }
    if (!document.hidden) refreshAnalyticsPeriodIfNeeded();
  });
  document.addEventListener('pointerover', function (e) {
    if (e.pointerType === 'touch' || !e.target.closest) return;
    var p = e.target.closest('[data-traffic-point]');
    if (p) showTrafficTooltip(p);
  });
  document.addEventListener('touchstart', function (e) {
    var p = e.target && e.target.closest ? e.target.closest('[data-traffic-point]') : null;
    if (p) showTrafficTooltip(p);
  }, { passive: true });
  document.addEventListener('focusin', function (e) {
    var p = e.target && e.target.closest ? e.target.closest('[data-traffic-point]') : null;
    if (p) showTrafficTooltip(p);
  });
  setInterval(refreshAnalyticsPeriodIfNeeded, 60000);
   applyTheme();
   parseRoute();
   initializeAuth();
   trackPageview();
 })();

